powerpagecomponent.content:
{
  "source": "{% extends 'OT Layout' %}
{% block content %}
{% comment %}
  Review detail: renders the questionnaire version issued to this review
  (PP-07, PP-08, PP-09).

  The chain is Checklist Version -> Section -> Question -> Question Version.
  Questions are read from the checklist version stamped on the review instance,
  and of each question's versions only the one in force on the review's
  reference day renders: the submission day once submitted, otherwise today
  (AD-015, BR-013, FR-030, FR-031). A retired version keeps its effective-to
  date and stays Active, so without that filter every version of a question
  rendered at once - which is how a submitted Tax review came to show Tax check
  reason three times and hold an answer on each. The server applies the same
  rule (ResponseRules.IsVersionEffective) to the submit gate and the outcome.

  Answerable by the assigned checker (AD-053). Both writes on this page go through an
  allowlisted trigger column and a synchronous plug-in rather than the Web API's own
  create/update/action verbs, for two different reasons. Answering PATCHes a JSON payload
  onto al_reviewinstance.al_answerrequest, because Power Pages refuses the al_response
  create's @odata.bind association - and a fail reason's $ref associate - with error
  90040106 regardless of table permissions; AnswerRequestPlugin parses the payload and
  AnswerWriter does the al_response create/update instead. Submitting PATCHes
  al_reviewinstance.al_submitrequested, because the Portals Web API cannot invoke the
  al_SubmitReview Custom API at all; SubmitRequestPlugin does that work instead of a Power
  Automate flow. Every rule that matters - the submission lock, the AD-023 column match,
  the option subset and AD-020 section ownership - is enforced by ResponseGuardPlugin, so
  nothing here is a security boundary (NFR-SEC-01).
{% endcomment %}

{% assign review_id = request.params['id'] %}

{% comment %}
  A claim lands here by case rather than by review id: the queue page cannot read the new
  instance's id over the Web API (the al_reviewinstance allowlist carries only the two
  trigger columns, and widening it would hand the reviewer the status column), but Liquid
  can, with no allowlist in the way. The open instance of that discipline assigned to the
  signed-in user is the one just created; if none is found the page reads as "no review
  selected", which is what a stale link should say.
{% endcomment %}
{% if review_id == null or review_id == empty %}
  {% assign case_param = request.params['case'] %}
  {% assign type_param = request.params['type'] %}
  {% if user and case_param and case_param != empty %}
    {% fetchxml by_case %}
    <fetch top="1">
      <entity name="al_reviewinstance">
        <attribute name="al_reviewinstanceid" />
        <filter type="and">
          <condition attribute="al_outcomecaseid" operator="eq" value="{{ case_param | xml_escape }}" />
          <condition attribute="al_assignedcontactid" operator="eq" value="{{ user.id }}" />
          <condition attribute="al_submittedon" operator="null" />
          {% if type_param and type_param != empty %}
          <condition attribute="al_reviewtype" operator="eq" value="{{ type_param | xml_escape }}" />
          {% endif %}
        </filter>
        <order attribute="createdon" descending="true" />
      </entity>
    </fetch>
    {% endfetchxml %}
    {% assign by_case_row = by_case.results.entities[0] %}
    {% if by_case_row %}
      {% assign review_id = by_case_row.al_reviewinstanceid %}
    {% endif %}
  {% endif %}
{% endif %}

{% if review_id == null or review_id == empty %}
  {% include 'OT Empty State' title: 'No review selected' message: 'Open a review from a worklist to see its questionnaire.' %}
{% else %}

  {% fetchxml review %}
  <fetch top="1">
    <entity name="al_reviewinstance">
      <attribute name="al_reviewinstanceid" />
      <attribute name="al_name" />
      <attribute name="al_reviewtype" />
      <attribute name="al_reviewstatus" />
      <attribute name="al_sequence" />
      <attribute name="al_startedon" />
      <attribute name="al_submittedon" />
      <attribute name="al_checklistversionid" />
      <attribute name="al_assignedcontactid" />
      <filter type="and">
        <condition attribute="al_reviewinstanceid" operator="eq" value="{{ review_id | xml_escape }}" />
      </filter>
      <link-entity name="al_outcomecase" from="al_outcomecaseid" to="al_outcomecaseid" link-type="outer" alias="case">
        <attribute name="al_outcomecaseid" />
        <attribute name="al_casereference" />
        <attribute name="al_clientname" />
        <attribute name="al_advisername" />
        <attribute name="al_adviserstatus" />
        <attribute name="al_advisercode" />
        <attribute name="al_paraplanner" />
        <attribute name="al_paraplannercode" />
        <attribute name="al_products" />
        <attribute name="al_casetype" />
        <attribute name="al_advicedate" />
        <attribute name="al_productsolutiontype" />
        <attribute name="al_samplesource" />
        <attribute name="al_taxcheckername" />
        <attribute name="al_aqscheckername" />
        <attribute name="al_checkdate" />
        <attribute name="al_preorpostcheck" />
        <attribute name="al_vulnerableclient" />
        <attribute name="al_taxcheckrequired" />
        <attribute name="al_taxteamdisposition" />
        <attribute name="al_checklistitems" />
      </link-entity>
    </entity>
  </fetch>
  {% endfetchxml %}

  {% assign rv = review.results.entities[0] %}

  {% if rv == null %}
    {% include 'OT Empty State' title: 'Review not available' message: 'This review does not exist, or you do not have permission to view it.' %}
  {% else %}

    {% assign cv_id = rv.al_checklistversionid.id %}

    {% comment %}
      The review's discipline, resolved once. 120910006 reads its third option differently
      on a Tax review (AD-055 amended), and both paths that draw that scale - the grid
      headings below and the OT Answer Options include - have to make the same reading. Held
      in one variable so they cannot drift apart, which is how the inline path came to draw
      an AQS question as a tax check.
    {% endcomment %}
    {% assign is_tax_review = false %}
    {% if rv.al_reviewtype.value == 120910200 %}{% assign is_tax_review = true %}{% endif %}

    {% comment %}
      AD-020 section ownership, keyed by the review's discipline. Filtering in the query
      rather than in the loop is what makes the Tax/AQS split structural: a Tax checker's
      page never receives an AQS section's questions at all, which is what PP-08's
      "no cross-discipline overwrite" needs. The same rule is enforced again server-side
      by ResponseGuardPlugin, because a filter in a page is not a security boundary
      (NFR-SEC-01).
    {% endcomment %}
    {% if rv.al_reviewtype.value == 120910200 %}
      {% assign owner_role = 120910100 %}
    {% else %}
      {% assign owner_role = 120910101 %}
    {% endif %}

    {% comment %}
      A submitted review is read-only (PP-11). The questionnaire renders for a submitted
      review too, so every control is disabled and the autosave script is not emitted at
      all. ResponseGuardPlugin refuses the write regardless; disabling the control is what
      stops a checker typing into a field that can never save.
    {% endcomment %}
    {% if rv.al_submittedon %}
      {% assign locked = true %}
    {% else %}
      {% assign locked = false %}
    {% endif %}

    {% comment %}
      AD-056: a reviewer reads every review but changes only their own. Because reading
      another reviewer's review is now intended, the page must say so and disable its
      controls - otherwise a checker types into fields that the table permissions will
      refuse on save. The permission chain is the actual boundary; this is what stops the
      user discovering it the hard way.
    {% endcomment %}
    {% if rv.al_assignedcontactid.id and rv.al_assignedcontactid.id == user.id %}
      {% assign mine = true %}
    {% else %}
      {% assign mine = false %}
    {% endif %}

    {% if locked or mine == false %}
      {% assign editable = false %}
    {% else %}
      {% assign editable = true %}
    {% endif %}

    <section class="ot-card" aria-labelledby="ot-review-summary">
      <h2 class="ot-card__title" id="ot-review-summary">
        {{ rv.al_reviewtype.label | escape }} review
        <span data-ot-review-status>{% include 'OT Status Badge' status: rv.al_reviewstatus.label %}</span>
      </h2>
      <dl class="ot-dl">
        <div>
          <dt>Case</dt>
          <dd>
            {% assign cid = rv['case.al_outcomecaseid'] %}
            {% if cid %}
              <a href="/case-details?id={{ cid }}">{{ rv['case.al_casereference'] | default: 'Untitled case' | escape }}</a>
            {% else %}
              {{ rv['case.al_casereference'] | default: '—' | escape }}
            {% endif %}
          </dd>
        </div>
        <div><dt>Client</dt><dd>{{ rv['case.al_clientname'] | default: '—' | escape }}</dd></div>
        <div><dt>Adviser</dt><dd>{{ rv['case.al_advisername'] | default: '—' | escape }}</dd></div>
        <div><dt>Checklist version</dt><dd>{{ rv.al_checklistversionid.name | default: '—' | escape }}</dd></div>
        <div><dt>Sequence</dt><dd>{{ rv.al_sequence | default: '—' }}</dd></div>
        <div><dt>Started</dt><dd>{{ rv.al_startedon | date: 'dd MMM yyyy' | default: '—' }}</dd></div>
        <div><dt>Submitted</dt><dd data-ot-submitted-on>{{ rv.al_submittedon | date: 'dd MMM yyyy' | default: '—' }}</dd></div>
      </dl>

      {% comment %}
        Keeping a copy of the checklist. The browser's print dialogue is the export - every
        platform's offers "Save as PDF" - and the print rules in outcome-testing.css strip
        the chrome so what lands in the file is this page's questionnaire and answers.

        No PDF library, for two reasons: Power Pages serves scripts only from an allowlisted
        set of CDNs, and a generated document would be a second description of this layout to
        keep in step with the one people read. The button itself is .ot-btn, which the print
        rules hide, so it never appears in the output.

        Offered on a submitted review only. What this exports is a record of the check, and
        before submission there is no check to record - the answers are still being edited,
        so a file saved from here would be a draft that reads exactly like a final one and
        carries no submission date to say otherwise. The button appears the moment the
        review is submitted and the page turns read-only.
      {% endcomment %}
      {% if rv.al_submittedon %}
        <p class="ot-print-action">
          <button type="button" class="ot-btn" data-ot-print>Save as PDF</button>
        </p>

        <script>
          (function () {
            'use strict';
            var button = document.querySelector('[data-ot-print]');
            if (!button) { return; }
            button.addEventListener('click', function () { window.print(); });
          })();
        </script>
      {% endif %}
    </section>

    {% if rv.al_submittedon %}
      <div class="ot-notice" role="status">
        <strong>Submitted {{ rv.al_submittedon | date: 'dd MMM yyyy' }}.</strong>
        This review is locked. Reopening or regrading is a T&amp;C Manager action and
        requires a recorded reason (AD-031).
      </div>
    {% elsif mine == false %}
      {% comment %}
        Reading another reviewer's work is intended under AD-056; changing it is not.
        Saying so plainly is better than presenting controls that fail on save.
      {% endcomment %}
      <div class="ot-notice" role="status">
        <strong>This review is assigned to someone else.</strong>
        You can read it, but only the assigned reviewer can record or change answers on it.
      </div>
    {% endif %}

    {% comment %}
      The Tax check's notes (project owner, 2026-09-19).

      On a submitted review only, and only where this review is not itself the Tax one.
      The Tax review renders Q-TAX-03 in its own questionnaire already, so repeating it
      above the form would show the same answer twice; what was missing is the AQS
      checker's view of it, which AD-020 filters out of their form by design.

      Submitted only, because before submission the page is the working form and the Tax
      note belongs to a check that is still the reviewer's own to change.
    {% endcomment %}
    {% if rv.al_submittedon and rv.al_reviewtype.value != 120910200 %}
      {% include 'OT Tax Notes' case_id: rv['case.al_outcomecaseid'] %}
    {% endif %}

    {% comment %}
      The document's header block (AD-098): the case fields in the order the Checker
      Checklist lays them out. Outcome Case columns captured at intake, not questions; read
      only here, as on the checklist itself. Choice columns come through the alias as
      option objects, so their label is read rather than their value.
    {% endcomment %}
    {% assign h_adviserstatus = rv['case.al_adviserstatus'] %}
    {% assign h_casetype = rv['case.al_casetype'] %}
    {% assign h_producttype = rv['case.al_productsolutiontype'] %}
    {% assign h_samplesource = rv['case.al_samplesource'] %}
    {% assign h_prepost = rv['case.al_preorpostcheck'] %}
    {% assign h_vulnerable = rv['case.al_vulnerableclient'] %}
    {% assign h_taxrequired = rv['case.al_taxcheckrequired'] %}
    {% assign h_taxdisposition = rv['case.al_taxteamdisposition'] %}
    {% comment %}
      The case header, held rather than emitted: on the document it is the first block of the
      form, so it is written inside the checklist wrapper below rather than as a card of its
      own above it. Outcome Case columns captured at intake, read only here as on the
      checklist itself. Choice columns come through the alias as option objects, so their
      label is read rather than their value.
    {% endcomment %}
    {% capture case_header %}
      <table class="meta">
        <tbody>
          {% comment %}
            The header a checker may correct (item 5, 2026-09-19: "other fields should be
            editable by the checkers excluding the references and IDs").

            Editable while this checker's own review is open, read-only once it is
            submitted - the same line the Tax row below draws, and the same line BR-012
            draws for the answers.

            IO reference stays read-only in BOTH branches. It identifies the case to the
            business and keys the import (BR-001), and it is not in the server's editable
            set either, so an edit naming it is refused whatever this page renders.

            Due date is not on this table at all. It is derived from the upload and locked
            for everyone (ImportRules.DueDateFor).

            The affordance, not the boundary. CaseHeaderRequestPlugin re-checks server-side
            that the caller holds an open review on THIS case; the page writes through a
            contact permission shared with the sign-off and the claim, so a request can be
            made by hand for any case id and hiding the inputs would enforce nothing
            (NFR-SEC-01).
          {% endcomment %}
          {% if locked == false %}
          <tr>
            <td class="lbl">Adviser name</td><td class="val"><input type="text" class="ot-hdr-input" data-ot-hdr="al_advisername" value="{{ rv['case.al_advisername'] | escape }}" aria-label="Adviser name" /></td>
            <td class="lbl">Adviser status</td><td class="val"><select class="ot-hdr-input" data-ot-hdr="al_adviserstatus" aria-label="Adviser status"><option value="">&mdash;</option><option value="120910500" {% if h_adviserstatus.value == 120910500 %}selected{% endif %}>PreCAS</option><option value="120910501" {% if h_adviserstatus.value == 120910501 %}selected{% endif %}>CAS</option><option value="120910502" {% if h_adviserstatus.value == 120910502 %}selected{% endif %}>Enhanced</option><option value="120910503" {% if h_adviserstatus.value == 120910503 %}selected{% endif %}>Watchlist</option></select></td>
          </tr>
          <tr>
            <td class="lbl">Adviser code</td><td class="val"><input type="text" class="ot-hdr-input" data-ot-hdr="al_advisercode" value="{{ rv['case.al_advisercode'] | escape }}" aria-label="Adviser code" /></td>
            <td class="lbl">Paraplanner</td><td class="val"><input type="text" class="ot-hdr-input" data-ot-hdr="al_paraplanner" value="{{ rv['case.al_paraplanner'] | escape }}" aria-label="Paraplanner" /></td>
          </tr>
          <tr>
            <td class="lbl">Paraplanner code</td><td class="val"><input type="text" class="ot-hdr-input" data-ot-hdr="al_paraplannercode" value="{{ rv['case.al_paraplannercode'] | escape }}" aria-label="Paraplanner code" /></td>
            <td class="lbl">Product(s)</td><td class="val"><input type="text" class="ot-hdr-input" data-ot-hdr="al_products" value="{{ rv['case.al_products'] | escape }}" aria-label="Products" /></td>
          </tr>
          <tr>
            <td class="lbl">Case type</td><td class="val"><select class="ot-hdr-input" data-ot-hdr="al_casetype" aria-label="Case type"><option value="">&mdash;</option><option value="120910510" {% if h_casetype.value == 120910510 %}selected{% endif %}>New advice</option><option value="120910511" {% if h_casetype.value == 120910511 %}selected{% endif %}>Ongoing</option><option value="120910512" {% if h_casetype.value == 120910512 %}selected{% endif %}>Review</option><option value="120910513" {% if h_casetype.value == 120910513 %}selected{% endif %}>Switch/Transfer</option></select></td>
            <td class="lbl">Date of meeting - Client contact</td><td class="val"><input type="date" class="ot-hdr-input" data-ot-hdr="al_advicedate" data-ot-no-future value="{{ rv['case.al_advicedate'] | date: 'yyyy-MM-dd' }}" aria-label="Date of meeting - Client contact" /></td>
          </tr>
          <tr>
            <td class="lbl">Product / solution type</td><td class="val"><select class="ot-hdr-input" data-ot-hdr="al_productsolutiontype" aria-label="Product or solution type"><option value="">&mdash;</option><option value="120910520" {% if h_producttype.value == 120910520 %}selected{% endif %}>Accumulation investment</option><option value="120910521" {% if h_producttype.value == 120910521 %}selected{% endif %}>Accumulation Pension</option><option value="120910522" {% if h_producttype.value == 120910522 %}selected{% endif %}>IHT</option><option value="120910523" {% if h_producttype.value == 120910523 %}selected{% endif %}>Protection</option><option value="120910524" {% if h_producttype.value == 120910524 %}selected{% endif %}>No change reviews</option></select></td>
            <td class="lbl">Sample source</td><td class="val"><select class="ot-hdr-input" data-ot-hdr="al_samplesource" aria-label="Sample source"><option value="">&mdash;</option><option value="120910530" {% if h_samplesource.value == 120910530 %}selected{% endif %}>Random</option><option value="120910531" {% if h_samplesource.value == 120910531 %}selected{% endif %}>Mandatory</option><option value="120910532" {% if h_samplesource.value == 120910532 %}selected{% endif %}>High Risk</option><option value="120910533" {% if h_samplesource.value == 120910533 %}selected{% endif %}>Thematic</option></select></td>
          </tr>
          <tr>
            {% comment %}
              Read-only from 2026-09-19 (item 2). Each checker REFLECTS the allocation on that
              review instance, stamped server-side by al_AssignCase and by a portal claim, so
              neither is free text. UpdateCaseDetailsPlugin and CaseHeaderRequestPlugin both
              refuse al_checkername now, and a text box the server rejects is worse than none.
            {% endcomment %}
            <td class="lbl">Tax Checker</td><td class="val">{{ rv['case.al_taxcheckername'] | default: 'Not yet allocated' | escape }}</td>
            <td class="lbl">AQS Checker</td><td class="val">{{ rv['case.al_aqscheckername'] | default: 'Not yet allocated' | escape }}</td>
          </tr>
          <tr>
            <td class="lbl">Check date</td><td class="val"><input type="date" class="ot-hdr-input" data-ot-hdr="al_checkdate" value="{{ rv['case.al_checkdate'] | date: 'yyyy-MM-dd' }}" aria-label="Check date" /></td>
            <td class="lbl"></td><td class="val"></td>
          </tr>
          <tr>
            <td class="lbl">Client name / initials</td><td class="val"><input type="text" class="ot-hdr-input" data-ot-hdr="al_clientname" value="{{ rv['case.al_clientname'] | escape }}" aria-label="Client name or initials" /></td>
            <td class="lbl">IO reference</td><td class="val">{{ rv['case.al_casereference'] | escape }}</td>
          </tr>
          <tr>
            <td class="lbl">Pre or post check</td><td class="val"><select class="ot-hdr-input" data-ot-hdr="al_preorpostcheck" aria-label="Pre or post check"><option value="">&mdash;</option><option value="120910540" {% if h_prepost.value == 120910540 %}selected{% endif %}>Pre</option><option value="120910541" {% if h_prepost.value == 120910541 %}selected{% endif %}>Post</option></select></td>
            <td class="lbl">Vulnerable client?</td><td class="val"><select class="ot-hdr-input" data-ot-hdr="al_vulnerableclient" aria-label="Vulnerable client"><option value="">&mdash;</option><option value="120910550" {% if h_vulnerable.value == 120910550 %}selected{% endif %}>Yes</option><option value="120910551" {% if h_vulnerable.value == 120910551 %}selected{% endif %}>No</option><option value="120910552" {% if h_vulnerable.value == 120910552 %}selected{% endif %}>Potentially vulnerable</option><option value="120910553" {% if h_vulnerable.value == 120910553 %}selected{% endif %}>N/A</option></select></td>
          </tr>
          {% else %}
          <tr><td class="lbl">Adviser name</td><td class="val">{{ rv['case.al_advisername'] | escape }}</td><td class="lbl">Adviser status</td><td class="val">{{ h_adviserstatus.label | escape }}</td></tr>
          <tr><td class="lbl">Adviser code</td><td class="val">{{ rv['case.al_advisercode'] | escape }}</td><td class="lbl">Paraplanner</td><td class="val">{{ rv['case.al_paraplanner'] | escape }}</td></tr>
          <tr><td class="lbl">Paraplanner code</td><td class="val">{{ rv['case.al_paraplannercode'] | escape }}</td><td class="lbl">Product(s)</td><td class="val">{{ rv['case.al_products'] | escape }}</td></tr>
          <tr><td class="lbl">Case type</td><td class="val">{{ h_casetype.label | escape }}</td><td class="lbl">Date of meeting - Client contact</td><td class="val">{{ rv['case.al_advicedate'] | date: 'dd MMM yyyy' }}</td></tr>
          <tr><td class="lbl">Product / solution type</td><td class="val">{{ h_producttype.label | escape }}</td><td class="lbl">Sample source</td><td class="val">{{ h_samplesource.label | escape }}</td></tr>
          <tr><td class="lbl">Tax Checker</td><td class="val">{{ rv['case.al_taxcheckername'] | default: 'Not yet allocated' | escape }}</td><td class="lbl">AQS Checker</td><td class="val">{{ rv['case.al_aqscheckername'] | default: 'Not yet allocated' | escape }}</td></tr>
          <tr><td class="lbl">Check date</td><td class="val">{{ rv['case.al_checkdate'] | date: 'dd MMM yyyy' }}</td><td class="lbl"></td><td class="val"></td></tr>
          <tr><td class="lbl">Client name / initials</td><td class="val">{{ rv['case.al_clientname'] | escape }}</td><td class="lbl">IO reference</td><td class="val">{{ rv['case.al_casereference'] | escape }}</td></tr>
          <tr><td class="lbl">Pre or post check</td><td class="val">{{ h_prepost.label | escape }}</td><td class="lbl">Vulnerable client?</td><td class="val">{{ h_vulnerable.label | escape }}</td></tr>
          {% endif %}
          {% comment %}
            The Tax team's own two fields (project owner, 2026-09-13). The document labels
            them "(Tax team to complete)" and "For Tax team usage", so it already assigns
            both to the Tax team; until now only the Code App could set them, and "For Tax
            team usage" is what decides whether an AQS check follows - Return to paraplanner
            ends the case at Tax with no AQS owed (UpdateCaseDetailsPlugin.DeriveRoute).

            Editable on a Tax review that has not been submitted, read-only everywhere else.
            A submitted review is immutable (BR-012) and its route was acted on at submit, so
            moving the disposition afterwards would contradict something already done;
            CaseHeaderRequestPlugin refuses it server-side on the review's status, and this
            is the affordance rather than the boundary.

            Deliberately NOT hidden by web role. The role is checked server-side against the
            contact's own roles, and hiding the control in Liquid would look like access
            control while enforcing nothing (NFR-SEC-01) - the same position the sign-off
            panel on OT Remediation records.
          {% endcomment %}
          {% comment %}
            The dash is a placeholder, not a choice: the request encodes an unchanged field as
            0 and CaseHeaderRequestPlugin reads 0 as "not sent", so selecting the dash could
            never clear a value - the page reported Saved and the value stayed. Disabled, so
            it shows only while the field is still empty. Clearing a recorded answer is not a
            Tax checker's edit; that is a case correction through al_UpdateCaseDetails.
          {% endcomment %}
          {% if rv.al_reviewtype.value == 120910200 and locked == false %}
          <tr>
            <td class="lbl">Tax check required<br>(Tax team to complete)</td>
            <td class="val">
              <select class="ot-field" id="ot-taxrequired" data-ot-header-field aria-label="Tax check required">
                <option value="" disabled>—</option>
                <option value="120910560" {% if h_taxrequired.value == 120910560 %}selected{% endif %}>Yes</option>
                <option value="120910561" {% if h_taxrequired.value == 120910561 %}selected{% endif %}>No</option>
              </select>
            </td>
            <td class="lbl">For Tax team usage</td>
            <td class="val">
              <select class="ot-field" id="ot-taxdisposition" data-ot-header-field aria-label="For Tax team usage">
                <option value="" disabled>—</option>
                <option value="120910570" {% if h_taxdisposition.value == 120910570 %}selected{% endif %}>Submit to AQS</option>
                <option value="120910571" {% if h_taxdisposition.value == 120910571 %}selected{% endif %}>Return to paraplanner</option>
              </select>
            </td>
          </tr>
          {% else %}
          <tr><td class="lbl">Tax check required<br>(Tax team to complete)</td><td class="val">{{ h_taxrequired.label | escape }}</td><td class="lbl">For Tax team usage</td><td class="val">{{ h_taxdisposition.label | escape }}</td></tr>
          {% endif %}

          {% comment %}
            No Save button (project owner, 2026-09-19). A header edit saves itself as it is
            made, the way an answer already does, and the submit is what finishes the
            review - so a button that said "Save header" was a second thing to remember on
            a form where nothing else has to be saved by hand.

            The row carries only the status line, and hides itself while there is nothing to
            say: an always-visible "Header" row with an empty cell reads as a field someone
            forgot to fill in. :has is already used for the sticky footer in this stylesheet.

            data-case-id lives here because the script needs the case whether or not the Tax
            row above it was rendered.
          {% endcomment %}
          {% if locked == false %}
          <tr id="ot-header-statusrow">
            <td class="lbl">Header</td>
            <td class="val" colspan="3">
              <span id="ot-header-status" role="status" aria-live="polite"
                    data-case-id="{{ cid }}"></span>
            </td>
          </tr>
          {% endif %}
        </tbody>
      </table>
    {% endcapture %}

    {% if cv_id == null %}
      {% include 'OT Empty State' title: 'No checklist version issued' message: 'This review has no checklist version, so no questions can be rendered.' %}
    {% else %}

      {% comment %}
        The day this review's questions are read against. Effective-from and
        effective-to are date-only columns, and RetireAndSucceedQuestion stamps the old
        version's effective-to and the successor's effective-from with the same date, so
        "in force" is from <= day < to.
      {% endcomment %}
      {% if rv.al_submittedon %}
        {% assign as_of = rv.al_submittedon | date: 'yyyy-MM-dd' %}
      {% else %}
        {% assign as_of = now | date: 'yyyy-MM-dd' %}
      {% endif %}

      {% fetchxml questions %}
      <fetch>
        <entity name="al_questionversion">
          <attribute name="al_questionversionid" />
          <attribute name="al_questiontext" />
          <attribute name="al_responsetype" />
          <attribute name="al_ismandatory" />
          <attribute name="al_versionnumber" />
          <attribute name="al_displayorder" />
          <filter type="and">
            <filter type="or">
              <condition attribute="al_effectivefrom" operator="null" />
              <condition attribute="al_effectivefrom" operator="on-or-before" value="{{ as_of }}" />
            </filter>
            <filter type="or">
              <condition attribute="al_effectiveto" operator="null" />
              <condition attribute="al_effectiveto" operator="gt" value="{{ as_of }}" />
            </filter>
          </filter>
          <link-entity name="al_question" from="al_questionid" to="al_questionid" alias="q">
            <attribute name="al_displayorder" />
            <attribute name="al_questioncode" />
            <link-entity name="al_section" from="al_sectionid" to="al_sectionid" alias="s">
              <attribute name="al_sectionid" />
              <attribute name="al_name" />
              <attribute name="al_displayorder" />
              <attribute name="al_helptext" />
              <attribute name="al_ownerrole" />
              <attribute name="al_sectioncode" />
              <attribute name="al_isoptional" />
              <filter type="and">
                <condition attribute="al_checklistversionid" operator="eq" value="{{ cv_id }}" />
                <condition attribute="al_ownerrole" operator="in">
                  <value>{{ owner_role }}</value>
                  <value>120910105</value>
                </condition>
                <filter type="or">
                  <condition attribute="al_effectivefrom" operator="null" />
                  <condition attribute="al_effectivefrom" operator="on-or-before" value="{{ as_of }}" />
                </filter>
                <filter type="or">
                  <condition attribute="al_effectiveto" operator="null" />
                  <condition attribute="al_effectiveto" operator="gt" value="{{ as_of }}" />
                </filter>
              </filter>
            </link-entity>
          </link-entity>
          <order entityname="s" attribute="al_displayorder" />
          <order entityname="q" attribute="al_displayorder" />
        </entity>
      </fetch>
      {% endfetchxml %}

      {% comment %}
        The sections this team owns, in the document's order - fetched separately, and the
        thing the questionnaire below actually iterates.

        The questions fetch above asks for section-then-question order with two root-level
        order elements carrying an entityname. The SDK honours that; this page's Liquid
        fetch does not - it applied only the question order, so every section's question 1
        came back before any section's question 2 and the whole form arrived interleaved
        (project owner's Tax and AQS PDFs, 2026-09-09). The rows are grouped by section here
        instead of relying on that ordering: this fetch's order is a plain root-entity order
        on al_section, which is applied, and within one section the question order from the
        fetch above is applied too. So the sequence no longer depends on cross-entity
        ordering working. Leave the orders above in place - they cost nothing and they are
        what the SDK and any future engine will use.
      {% endcomment %}
      {% fetchxml sections %}
      <fetch>
        <entity name="al_section">
          <attribute name="al_sectionid" />
          <attribute name="al_sectioncode" />
          <attribute name="al_displayorder" />
          <attribute name="al_isoptional" />
          <filter type="and">
            <condition attribute="al_checklistversionid" operator="eq" value="{{ cv_id | xml_escape }}" />
            <condition attribute="al_ownerrole" operator="in">
              <value>{{ owner_role }}</value>
              <value>120910105</value>
            </condition>
            <filter type="or">
              <condition attribute="al_effectivefrom" operator="null" />
              <condition attribute="al_effectivefrom" operator="on-or-before" value="{{ as_of }}" />
            </filter>
            <filter type="or">
              <condition attribute="al_effectiveto" operator="null" />
              <condition attribute="al_effectiveto" operator="gt" value="{{ as_of }}" />
            </filter>
          </filter>
          <order attribute="al_displayorder" />
        </entity>
      </fetch>
      {% endfetchxml %}

      {% fetchxml responses %}
      <fetch>
        <entity name="al_response">
          <attribute name="al_responseid" />
          <attribute name="al_questionversionid" />
          <attribute name="al_answertext" />
          <attribute name="al_answerrichtext" />
          <attribute name="al_answerchoice" />
          <attribute name="al_answerchoices" />
          <attribute name="al_answerdate" />
          <filter type="and">
            <condition attribute="al_reviewinstanceid" operator="eq" value="{{ review_id | xml_escape }}" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {% comment %}
        Fail reasons (FR-013, AD-096). Reference data, fetched once, for the standalone
        File Quality fail points block rendered before the File Quality outcome section.

        Both teams get the whole list. The document draws one undivided twenty-row table, and
        the category is a grouping of the reasons rather than a split of who may pick them
        (project owner, 2026-09-09). This used to filter by category - Tax check to the Tax
        team, the other three to AQS - which was an inference from the prefixes, and it left a
        Tax reviewer who found a record-keeping failure with nowhere to record it.

        The two teams' ticks still cannot collide: each hangs off that team's own File quality
        outcome answer (Q-FQ-01 for AQS, Q-FQTAX-01 for Tax) through the response-keyed
        intersect, and ReconcileFailReasons only ever touches ids this page rendered.
      {% endcomment %}
      {% fetchxml failreasons %}
      <fetch>
        <entity name="al_failreason">
          <attribute name="al_failreasonid" />
          <attribute name="al_name" />
          <attribute name="al_category" />
          <attribute name="al_displayorder" />
          <order attribute="al_displayorder" />
        </entity>
      </fetch>
      {% endfetchxml %}

      {% fetchxml selectedreasons %}
      <fetch>
        <entity name="al_failreason">
          <attribute name="al_failreasonid" />
          <link-entity name="al_al_failreason_al_response" from="al_failreasonid" to="al_failreasonid" intersect="true">
            <link-entity name="al_response" from="al_responseid" to="al_responseid" alias="r">
              <attribute name="al_responseid" />
              <filter type="and">
                <condition attribute="al_reviewinstanceid" operator="eq" value="{{ review_id | xml_escape }}" />
              </filter>
            </link-entity>
          </link-entity>
        </entity>
      </fetch>
      {% endfetchxml %}

      {% comment %}
        Flattened to a delimited key list so the per-checkbox test is a string match
        rather than a nested loop over every pair for all 42 questions.
      {% endcomment %}
      {% capture selected_reason_pairs %}{% for s in selectedreasons.results.entities %}|{{ s['r.al_responseid'] }}~{{ s.al_failreasonid }}{% endfor %}|{% endcapture %}

      {% assign qrows = questions.results.entities %}
      {% assign arows = responses.results.entities %}

      {% comment %}
        The Checklist header section (project owner, 2026-09-19). What the paraplanner
        ticked in the Intelligent Office task, which is why this case is being checked.

        Drawn by OT Checklist Items, which the case record page includes as well, so the
        two pages cannot come to disagree about what the column means or how a blank line
        in it is treated. The card style is the one that sits around a form; the case page
        asks for the sheet style instead.
      {% endcomment %}
      {% include 'OT Checklist Items' items: rv['case.al_checklistitems'] variant: 'card' %}

      {% if qrows.size == 0 %}
        {% include 'OT Empty State' title: 'No questions in this version' message: 'The checklist version issued to this review has no sections or questions.' %}
      {% else %}

        {% comment %}
          The questionnaire. Each question renders the control matching its response
          type and writes the AD-023 typed column. The wrapper carries the review id so
          the autosave script does not have to re-parse the query string.
        {% endcomment %}
        <div class="ot-checklist" data-ot-questionnaire data-review-id="{{ rv.al_reviewinstanceid }}">
        <div class="doc-footer">Outcome Testing Checker Checklist | V5 Draft</div>
        <h1>Outcome Testing - Checker Checklist</h1>
        {{ case_header }}
        {% comment %}
          The document's blocks (AD-098). The checklist model holds Section then Question
          with no grouping level, but the Checker Checklist lays its sections out under its
          own headings: E1 to E5 together under "Suitability core checks" as one table headed
          "Suitability test point", the Tax check as "File Quality - Tax check section", and
          so on. So each section is read into the document's block by its code, here and in
          the app (checklistForm.ts, formBlocks), and a card opens per block rather than per
          section. A section the document does not know keeps its own name.

          A grid block renders its questions as rows of one table with a radio per tick
          column, which is the document's layout. The row itself is the autosave root
          (data-ot-answer): the radios sit in the tick cells and the status line in the
          question cell, so bind() finds everything it needs inside the row exactly as it
          did inside the old div. A question whose response type is not the block's scale
          spans the tick columns with its usual control.
        {% endcomment %}
        {% assign current_blk = '' %}
        {% assign current_section = '' %}
        {% assign blk_layout = 'inline' %}
        {% assign prev_help = '' %}
        {% assign ncols = 2 %}
        {% comment %}
          The tick box the document draws on E2's outcome lens row, and on no other. It is a
          question of its own (Q-E2-LENS, display order last in its section), so it is picked
          up here as the loop passes it and held until the lens row is written - which happens
          once the section is finished, so the capture is always ready in time. Recognised by
          the -LENS code rather than by the section, matching checklistForm.ts isLensTick.
        {% endcomment %}
        {% assign lens_tick_id = '' %}
        {% assign lens_tick_cell = '' %}
        {% assign lens_tick_span = 0 %}
        {% comment %}
          The advice quality grade, carried forward so the primary root cause below knows
          whether to draw itself (item 3, 2026-09-19). A passing file has no cause to name,
          and GradingRules is where that is decided for real - it is what excuses Q-GR-02 at
          submission and what clears a cause recorded before the grade changed. This is only
          the drawing half.

          Captured as the loop passes the grade rather than looked up: Q-GR-01 is display
          order 1 and Q-GR-02 is order 2 in the one section, so the grade is always seen
          first. grade_seen is what makes that safe rather than assumed - if the two were
          ever reordered the grade would be unknown at the root cause, and an unknown grade
          draws the row, which is the direction that leaves a checker able to answer.
        {% endcomment %}
        {% assign grade_seen = false %}
        {% assign grade_value = '' %}
        {% comment %}
          Whether any Suitability core check has been answered Insufficient evidence, which
          takes PASS and PASS WITH ISSUES off the advice quality grade (item 10, 2026-09-19).

          Accumulated as the loop passes E1 to E5, which it does before Judgement and grading
          - S-GRADE is the last section in display order, and the grade is the only thing this
          feeds. GradingRules.SuitabilityGradeRefusal is the authority: it refuses the write in
          ResponseGuardPlugin and again in the submit command, so what this drives is which
          options the page offers, never which ones can be saved.
        {% endcomment %}
        {% assign suitability_insufficient = false %}
        {% comment %}
          Sections outer, that section's questions inner. The rows are matched on the section
          CODE rather than the section id, because the code is a plain string on both sides
          while an aliased guid's type through Liquid is not something to bet the whole form
          on - and the code is already what every block decision below is made from.

          first_row replaces forloop.first: the loop that opens and closes the block tables is
          no longer the outer one, so "have we opened a table yet" has to be state rather than
          a loop position. The last block is closed after both loops for the same reason.
        {% endcomment %}
        {% assign first_row = true %}
        {% for sec in sections.results.entities %}
        {% comment %}
          The shape of a section this template does not know, derived once per section
          rather than once per question row (which is where the block below used to sit, so
          a ten-question added section re-scanned every row ten times). Read against the
          section code, which is the same match the inner loop makes. sec_rt is the one
          response type every scale-typed question in the section agrees on, or 0 when it
          carries none; sec_mixed is set when two scales meet. Consumed under `unless known`
          below, where the seeded codes have already been recognised.
        {% endcomment %}
        {% assign sec_rt = 0 %}
        {% assign sec_mixed = false %}
        {% for q in qrows %}
          {% if q['s.al_sectioncode'] == sec.al_sectioncode %}
            {% assign qrt = q.al_responsetype.value %}
            {% if qrt == 120910006 or qrt == 120910008 or qrt == 120910009 %}
              {% if sec_rt == 0 %}
                {% assign sec_rt = qrt %}
              {% elsif sec_rt != qrt %}
                {% assign sec_mixed = true %}
              {% endif %}
            {% endif %}
          {% endif %}
        {% endfor %}
        {% for qv in qrows %}
          {% if qv['s.al_sectioncode'] == sec.al_sectioncode %}
          {% assign sid = qv['s.al_sectionid'] %}
          {% assign scode = qv['s.al_sectioncode'] %}
          {% comment %}
            The Suitability core checks, by section code rather than by display name, as the
            batch asked. This is a substring test because this site's Liquid has no prefix
            filter to rely on (see the filter limits recorded for OT Case List); the server's
            GradingRules.IsSuitabilitySection is the exact rule - S-E followed by a digit -
            and it is the one that decides. The two agree on every section that exists.
          {% endcomment %}
          {% assign is_suitability = false %}
          {% if scode contains 'S-E' %}{% assign is_suitability = true %}{% endif %}
          {% assign sname = qv['s.al_name'] %}
          {% assign shelp = qv['s.al_helptext'] %}
          {% assign soptional = qv['s.al_isoptional'] %}

          {% comment %}
            The block this section belongs to. Every section carries a code, so the fallback
            is only there for one seeded without.

            This was `scode | default: sid`, and it is an explicit if now only because the
            variable it assigned used to be called `block` - a name this engine will not let
            you assign, the page body being inside a block tag - so it never varied, the
            boundary below fired once for the whole form, and the fail points block, which
            hangs off `blk == 'S-FQ'`, never rendered at all. The rename to blk is the fix.
            Nothing here proves the `default` filter was at fault: the summary card above uses
            it half a dozen times and renders correctly. It is written out longhand because an
            if cannot be misread, not because the filter was found guilty of anything.
          {% endcomment %}
          {% if scode != blank %}
            {% assign blk = scode %}
          {% else %}
            {% assign blk = sid %}
          {% endif %}
          {% assign blk_title = sname %}
          {% assign blk_intro = shelp %}
          {% assign layout = 'inline' %}
          {% assign grid_rt = 0 %}
          {% assign grid_col = 'Check' %}
          {% assign subsections = false %}
          {% assign known = false %}
          {% comment %}
            Written as if / elsif on one value at a time, deliberately.

            This was a case block on scode with two multi-value whens - S-FQOUT or S-FQTAX,
            and S-E1 through S-E5. Multi-value "when" is an extension, not core Liquid, and
            when it does not match there is no error: the case simply falls through, every E
            section keeps its own name and inline layout, and the document's "Suitability
            core checks" / "Suitability test point" table never appears at all. That is
            precisely the symptom the project owner reported twice (AD-098, and again
            2026-09-09), so the construct is gone rather than trusted. One test per code.

            NOTE FOR ANY COMMENT IN THIS FILE: never write Liquid tag delimiters inside one.
            This engine parses the contents of a comment block, so a tag named in passing is
            opened for real - and an unclosed one turns the endcomment into "Unknown tag
            'endcomment'" and takes the whole page down. Name tags in prose, without braces.
          {% endcomment %}
          {% if scode == 'S-TAX' %}
            {% assign known = true %}
            {% assign blk_title = 'File Quality - Tax check section' %}
          {% elsif scode == 'S-AMLCRA' %}
            {% assign known = true %}
            {% assign blk_title = 'File Quality - AML and CRA checking points' %}
            {% assign layout = 'grid' %}{% assign grid_rt = 120910008 %}
          {% elsif scode == 'S-FQOUT' %}
            {% assign known = true %}
            {% assign blk = 'S-FQ' %}
            {% assign blk_title = 'File Quality Outcome' %}
          {% elsif scode == 'S-FQTAX' %}
            {% assign known = true %}
            {% assign blk = 'S-FQ' %}
            {% assign blk_title = 'File Quality Outcome' %}
          {% elsif scode == 'S-E1' or scode == 'S-E2' or scode == 'S-E3' or scode == 'S-E4' or scode == 'S-E5' %}
            {% assign known = true %}
            {% assign blk = 'S-E' %}
            {% assign blk_title = 'Suitability core checks' %}
            {% assign blk_intro = 'Suitability core checks are shown in a consistent Pass/Fail format against each test point.' %}
            {% assign layout = 'grid' %}{% assign grid_rt = 120910006 %}{% assign grid_col = 'Suitability test point' %}
            {% assign subsections = true %}
          {% elsif scode == 'S-CRP' %}
            {% assign known = true %}
            {% assign blk_title = 'Centralised Retirement Proposition' %}
            {% assign blk_intro = 'Complete this section where retirement income planning or decumulation advice is in scope.' %}
            {% assign layout = 'grid' %}{% assign grid_rt = 120910006 %}{% assign grid_col = 'Centralised Retirement Proposition test point' %}
          {% elsif scode == 'S-CD' %}
            {% assign known = true %}
            {% assign blk_title = 'Consumer Duty overlay' %}
            {% assign layout = 'grid' %}{% assign grid_rt = 120910009 %}{% assign grid_col = 'Outcome' %}
          {% elsif scode == 'S-GRADE' %}
            {% assign known = true %}
            {% assign blk_title = 'Checker judgement and grading' %}
          {% endif %}

          {% comment %}
            A section added through checklist administration (AD-123) carries a code this
            template has never seen, so the chain above leaves it on the defaults: layout
            inline, which opens a meta table, and no tick columns at all. Every seeded
            section whose questions use the same scale opens a ruled grid instead, so an
            added section came out in a different table shape from the rest of the document
            - the same stylesheet, drawn wrong.

            So where the code is not one this template knows, the shape is taken from the
            section's own questions rather than from its name. One pass over this section's
            rows, made once per section at the top of the outer loop: if every scale-typed
            question agrees on one response type, that is the grid and its tick columns are
            the ones the chain below picks for that type; a section mixing two scales, or
            carrying none, stays a meta table, which is what a free-text or date section
            should be.

            Guarded on `known` rather than on the layout value, deliberately. S-TAX and
            S-GRADE are recognised and are meta on the document, so "still inline" cannot
            tell an unrecognised section from a recognised flat one - deriving on that test
            would redraw two seeded blocks the reference file pins (AD-098, AD-104).
          {% endcomment %}
          {% unless known %}
            {% if sec_rt != 0 and sec_mixed == false %}
              {% assign layout = 'grid' %}
              {% assign grid_rt = sec_rt %}
            {% endif %}
          {% endunless %}

          {% comment %}
            A KNOWN block declares its scale above rather than deriving it, so the reference
            document can pin its columns. That holds only while its questions still answer on
            it, and AD-123 checklist administration can retype them: S-AMLCRA had three of
            its five moved to 120910006 and went on heading itself Yes / No / N/A, describing
            the two it had left. Where a declared grid no longer matches its questions, the
            questions win - they are what a checker is actually ticking.

            Only a declared GRID is re-read. S-TAX and S-GRADE declare no scale and are meta
            on the document, so the guard above still protects what it was written to
            protect: neither can reach this, and the reference blocks stay pinned.

            Read over the questions that answer on a tick scale, and those alone. A section
            may also carry a written, dated or formatted question - S-E2 carries its lens
            tick on 120910007 - and such a row has never had a cell under these columns
            anyway: it is drawn inline by the row chain below, on both surfaces. Counting it
            here would have taken Suitability off its grid on the strength of a row that was
            never in it. formBlocks reads the same rows in the app.

            Agreeing questions re-head the grid; disagreeing ones take the block to a meta
            table where each row draws its own options and no column header can misdescribe
            it.
          {% endcomment %}
          {% if known and layout == 'grid' %}
            {% if sec_mixed or sec_rt == 0 %}
              {% assign layout = 'inline' %}
              {% assign grid_rt = 0 %}
            {% elsif sec_rt != grid_rt %}
              {% assign grid_rt = sec_rt %}
            {% endif %}
          {% endif %}

          {% comment %}
            The tick columns for whichever scale this block is headed by. A `case` on an
            integer is the same gamble as the one above, so this is an if chain too.
          {% endcomment %}
          {% comment %}
            120910302 reads "Pass with issues" on a Tax review and "Insufficient evidence"
            everywhere else (AD-055 amended, 2026-09-13). Same value, same scale, same saved
            answer - the Tax check alone was reworded, and 120910006 is shared with the
            suitability grid, so the wording cannot sit on the scale.

            Q-TAX-02 itself is drawn inline and takes its label from OT Answer Options, so
            this branch reaches it only through a section added by checklist administration
            (AD-123) whose questions all use this scale. Keyed on the REVIEW's discipline
            rather than the section's owner role, because "for tax checks" is what was
            reworded: a Both-owned section answered on a Tax review is a tax check, and a
            Tax-owned section cannot appear on an AQS review at all.
          {% endcomment %}
          {% if grid_rt == 120910006 %}
            {% assign gvalues = '120910300,120910301,120910302' | split: ',' %}
            {% if is_tax_review %}
              {% assign glabels = 'Pass,Fail,Pass with issues' | split: ',' %}
            {% else %}
              {% assign glabels = 'Pass,Fail,Insufficient evidence' | split: ',' %}
            {% endif %}
          {% elsif grid_rt == 120910008 %}
            {% assign gvalues = '120910305,120910306,120910307' | split: ',' %}
            {% assign glabels = 'Yes,No,N/A' | split: ',' %}
          {% elsif grid_rt == 120910009 %}
            {% assign gvalues = '120910305,120910306,120910302' | split: ',' %}
            {% assign glabels = 'Yes,No,Insufficient evidence' | split: ',' %}
          {% endif %}

          {% comment %}
            The document's blocks, drawn as the document draws them: an h2, the intro line
            where there is one, then one table. No cards, no badges, no scroll boxes - the
            page around this keeps the site's brand, the form itself is the V8 checklist.

            Three table shapes, matching the reference build:
              .grid  - a test-point table, 55% label plus one 15% tick column per scale value
              .meta  - a label / value table, 17% label plus the control across the rest
              .fails - the fail points table, 90% reason plus a 10% Tick column
          {% endcomment %}
          {% if blk != current_blk %}
            {% unless first_row %}
              {% if blk_subsections and prev_help != blank %}
                <tr class="lens"{% if lens_tick_id != '' %} data-ot-answer data-question-version="{{ lens_tick_id }}" data-response-type="120910007" data-column="choice"{% endif %}><td colspan="{{ ncols | minus: lens_tick_span }}"><em>Outcome lens:</em> {{ prev_help | escape }}</td>{{ lens_tick_cell }}</tr>{% assign lens_tick_id = '' %}{% assign lens_tick_cell = '' %}{% assign lens_tick_span = 0 %}
              {% endif %}
              </tbody>
            </table>
            {% endunless %}
            {% assign current_blk = blk %}
            {% assign current_section = '' %}
            {% assign blk_layout = layout %}
            {% assign blk_subsections = subsections %}
            {% assign blk_rt = grid_rt %}
            {% if layout == 'grid' %}
              {% assign ncols = gvalues.size | plus: 1 %}
            {% else %}
              {% assign ncols = 4 %}
            {% endif %}

            {% comment %}
              File Quality - Fail points (AD-096, superseding AD-054). On the document this
              is its own block, between the checking points and the File Quality outcome,
              and it is rendered as one here: the document's two-column table of every
              reason against a Tick box, the same table the app draws (checklistForm.ts,
              failPoints), not a picker under every non-pass answer. The ticks are recorded
              against the File quality outcome answer - the first question of the outcome
              block, which is what qv is at this boundary - because the intersect is
              response-keyed (AD-025) and that is the answer these reasons explain. The
              outcome question's autosave binds the list through data-ot-failpoints-for, so
              a tick saves like any other change to that answer.
            {% endcomment %}
            {% if blk == 'S-FQ' %}
              {% assign fq_existing = null %}
              {% for a in arows %}
                {% if a.al_questionversionid.id == qv.al_questionversionid %}{% assign fq_existing = a %}{% endif %}
              {% endfor %}
              <h2>File Quality &ndash; Fail points</h2>
              <table class="fails" data-ot-failpoints-for="{{ qv.al_questionversionid }}">
                <thead>
                  <tr>
                    <th class="label">File Quality fail reason</th>
                    <th class="tick">Tick</th>
                  </tr>
                </thead>
                <tbody>
                  {% for fr in failreasons.results.entities %}
                    <tr>
                      <td class="label"><label for="fr-{{ fr.al_failreasonid }}">{{ fr.al_name | escape }}</label></td>
                      <td class="tick">{% capture pairkey %}|{{ fq_existing.al_responseid }}~{{ fr.al_failreasonid }}{% endcapture %}<input type="checkbox" class="cc-box" id="fr-{{ fr.al_failreasonid }}" data-ot-reason value="{{ fr.al_failreasonid }}"{% unless editable %} disabled{% endunless %}{% if fq_existing.al_responseid and selected_reason_pairs contains pairkey %} checked{% endif %} /></td>
                    </tr>
                  {% endfor %}
                </tbody>
              </table>
            {% endif %}

            {% comment %}
              An optional section may be left blank at submit (AD-123). The marker sits on
              the block heading only where the block is one section; a block that folds
              several sections together - Suitability, File Quality Outcome - carries the
              flag of whichever section opened it, which would mislabel the rest. Those
              get the marker on their own subsection row further down instead.
            {% endcomment %}
            <h2>{{ blk_title | escape }}{% unless blk_subsections %}{% if soptional %} <span class="ot-optional">Optional</span>{% endif %}{% endunless %}</h2>
            {% if blk_intro != blank %}
              <p class="intro">{{ blk_intro | escape }}</p>
            {% endif %}
            {% if layout == 'grid' %}
            <table class="grid">
              <thead>
                <tr>
                  <th class="label">{{ grid_col }}</th>
                  {% for l in glabels %}<th class="opt">{{ l }}</th>{% endfor %}
                </tr>
              </thead>
              <tbody>
            {% else %}
            <table class="meta">
              <tbody>
            {% endif %}
          {% endif %}

          {% if sid != current_section %}
            {% if blk_subsections %}
              {% if current_section != '' and prev_help != blank %}
                <tr class="lens"{% if lens_tick_id != '' %} data-ot-answer data-question-version="{{ lens_tick_id }}" data-response-type="120910007" data-column="choice"{% endif %}><td colspan="{{ ncols | minus: lens_tick_span }}"><em>Outcome lens:</em> {{ prev_help | escape }}</td>{{ lens_tick_cell }}</tr>{% assign lens_tick_id = '' %}{% assign lens_tick_cell = '' %}{% assign lens_tick_span = 0 %}
              {% endif %}
              <tr class="section"><td colspan="{{ ncols }}">{{ scode | remove_first: 'S-' }}. {{ sname | escape }}{% if soptional %} <span class="ot-optional">Optional</span>{% endif %}</td></tr>
            {% endif %}
            {% assign current_section = sid %}
            {% assign prev_help = shelp %}
          {% endif %}

          {% assign qv_id = qv.al_questionversionid %}
          {% assign rt = qv.al_responsetype.value %}

          {% assign existing = null %}
          {% for a in arows %}
            {% if a.al_questionversionid.id == qv_id %}{% assign existing = a %}{% endif %}
          {% endfor %}

          {% if rt == 120910000 or rt == 120910001 %}{% assign column = 'text' %}
          {% elsif rt == 120910011 %}{% assign column = 'richtext' %}
          {% elsif rt == 120910002 %}{% assign column = 'date' %}
          {% elsif rt == 120910004 %}{% assign column = 'choices' %}
          {% else %}{% assign column = 'choice' %}
          {% endif %}

          {% comment %}
            A ticked answer carries no free-text box. The Checker Checklist gives a tick
            column and nothing else against each test point, and the only free text the
            document asks for is its own questions - Case notes, Fail observation, Even
            Better If... - which render as multiline questions in their own right. The
            "Evidence or observation" box that used to sit under every non-pass answer was
            never on the form, so it is gone, and the reveal rule that opened it with it.

            The fail reasons used to sit here too, under every non-pass answer (AD-054).
            They are one standalone block now (AD-096).
          {% endcomment %}
          {% capture chosen_value %}{{ existing.al_answerchoice.value }}{% endcapture %}

          {% if rt == 120910010 %}
            {% assign grade_seen = true %}
            {% assign grade_value = chosen_value %}
          {% endif %}

          {% if is_suitability and chosen_value == '120910302' %}
            {% assign suitability_insufficient = true %}
          {% endif %}

          {% assign qcode = qv['q.al_questioncode'] %}
          {% if qcode contains '-LENS' %}
            {% comment %}
              One box, not a Yes / No pair, because that is what the document draws: ticked
              records Yes (120910305), untouched records nothing. The lens row itself becomes
              the autosave root, so bind() finds this input and saves it like any other answer
              - there is no status line on that row, and show() already tolerates its absence.
            {% endcomment %}
            {% assign lens_tick_id = qv_id %}
            {% assign lens_tick_span = 1 %}
            {% capture lens_tick_cell %}<td class="optcell"><input type="checkbox" class="cc-box" value="120910305" data-ot-input aria-label="{{ qv.al_questiontext | escape }}"{% unless editable %} disabled{% endunless %}{% if chosen_value == '120910305' %} checked{% endif %} /></td>{% endcapture %}

          {% elsif blk_layout == 'grid' and rt == blk_rt %}
            <tr data-ot-answer{% if is_suitability %} data-ot-suitability{% endif %}
                data-question-version="{{ qv_id }}"
                data-response-id="{{ existing.al_responseid }}"
                data-response-type="{{ rt }}"
                data-column="choice">
              <td class="label">{{ qv.al_questiontext | escape }}{% if qv.al_ismandatory %}<span class="ot-required">Required</span>{% endif %}<span class="ot-answer__status" data-ot-status aria-live="polite"></span></td>
              {% for v in gvalues %}
                <td class="optcell"><input type="radio" class="cc-box" name="q-{{ qv_id }}" id="q-{{ qv_id }}-{{ v }}" value="{{ v }}" data-ot-input{% unless editable %} disabled{% endunless %}{% if chosen_value == v %} checked{% endif %} /><label class="sr-only" for="q-{{ qv_id }}-{{ v }}">{{ qv.al_questiontext | escape }}: {{ glabels[forloop.index0] }}</label></td>
              {% endfor %}
            </tr>

          {% elsif rt == 120910003 %}
            {% comment %}
              Primary root cause. The document lays its nine causes out as a 3x3 grid under
              their own heading rather than as a row of an adjacent table, so it breaks out
              of the block's table into one of its own. The table is the autosave root: bind()
              looks for its inputs and its status line inside whatever carries data-ot-answer,
              and a table serves as well as a row.
            {% endcomment %}
              </tbody>
            </table>
            {% assign rcvalues = '120910320,120910321,120910322,120910323,120910324,120910325,120910326,120910327,120910328' | split: ',' %}
            {% assign rclabels = 'FactFind quality,Risk / capacity mismatch,Research / rationale,Charges / value,Client communication,Process / documentation,AML / CRA,Retirement Proposition,Adviser judgement' | split: ',' %}
            {% comment %}
              Shown only once the grade says the file did not pass - "visible and required
              only when the Advice quality grade is anything other than Pass", and nothing is
              not anything, so an ungraded review does not draw it either.

              Decided here rather than left to the script so the page arrives right, and so a
              submitted review, which renders no script at all, reads the same way.

              grade_seen is separate from grade_value because an unanswered grade and an
              unreached one are not the same thing: if the two questions were ever reordered
              the grade would be unreached here, and the block is drawn in that case, which is
              the direction that leaves a checker able to answer.
            {% endcomment %}
            {% assign hide_rootcause = false %}
            {% if grade_seen %}
              {% if grade_value == '' or grade_value == '120910300' %}{% assign hide_rootcause = true %}{% endif %}
            {% endif %}
            <table class="rootcause"
                   data-ot-answer
                   data-ot-rootcause
                   data-question-version="{{ qv_id }}"
                   data-response-id="{{ existing.al_responseid }}"
                   data-response-type="{{ rt }}"
                   data-column="choice"{% if hide_rootcause %} hidden{% endif %}>
              <tbody>
                <tr><th colspan="3">{{ qv.al_questiontext | escape }}{% if qv.al_ismandatory %}<span class="ot-required">Required</span>{% endif %}<span class="ot-answer__status" data-ot-status aria-live="polite"></span></th></tr>
                <tr>
                {% for v in rcvalues %}
                  <td><label class="opt wrap"><input type="radio" class="cc-box" name="q-{{ qv_id }}" value="{{ v }}" data-ot-input{% unless editable %} disabled{% endunless %}{% if chosen_value == v %} checked{% endif %} /> {{ rclabels[forloop.index0] }}</label></td>
                  {% if forloop.index == 3 or forloop.index == 6 %}</tr><tr>{% endif %}
                {% endfor %}
                </tr>
              </tbody>
            </table>
            <table class="meta">
              <tbody>

          {% else %}
            {% comment %}
              A Suitability core check reaches this branch too, where AD-146 has taken its
              block off the grid. The marker goes on both paths, so the grade restriction does
              not quietly stop watching a section because a question in it was retyped.
            {% endcomment %}
            <tr data-ot-answer{% if is_suitability %} data-ot-suitability{% endif %}
                data-question-version="{{ qv_id }}"
                data-response-id="{{ existing.al_responseid }}"
                data-response-type="{{ rt }}"
                data-column="{{ column }}">
              <td class="{% if blk_layout == 'grid' %}label{% else %}lbl{% endif %}">{{ qv.al_questiontext | escape }}{% if qv.al_ismandatory %}<span class="ot-required">Required</span>{% endif %}<span class="ot-answer__status" data-ot-status aria-live="polite"></span></td>
              <td colspan="{{ ncols | minus: 1 }}">
              {% if column == 'text' %}
                {% if rt == 120910001 %}
                  <textarea data-ot-input{% unless editable %} disabled{% endunless %} aria-label="{{ qv.al_questiontext | escape }}">{{ existing.al_answertext | escape }}</textarea>
                {% else %}
                  <input type="text" data-ot-input{% unless editable %} disabled{% endunless %} value="{{ existing.al_answertext | escape }}" aria-label="{{ qv.al_questiontext | escape }}" />
                {% endif %}

              {% elsif column == 'richtext' %}
                {% comment %}
                  A Rich text answer (item 7, 2026-09-19). contenteditable with a small
                  toolbar rather than an editor library: this site loads no third-party
                  script and carries no JS web file at all, so a CDN would be a first here
                  and a new thing for its content security policy to allow. The vocabulary
                  the toolbar offers is exactly the vocabulary HtmlSanitiser keeps, so
                  nothing a checker can press produces markup the save then discards.

                  The stored value is emitted as markup deliberately. It is the one value on
                  this page that is not escaped, and that is safe because it cannot reach the
                  column unsanitised: ResponseGuardPlugin cleans al_answerrichtext
                  pre-operation on al_response itself, so every write is reduced to the
                  allow-list whatever sent it - this page, the Code App, or a PATCH made by
                  hand at an existing row.

                  Read-only renders the same markup without the toolbar, so a submitted
                  answer reads as it did while it was being written.
                {% endcomment %}
                {% if editable %}
                <div class="ot-rte">
                  <div class="ot-rte__bar" role="toolbar" aria-label="Formatting">
                    <button type="button" class="ot-rte__btn" data-ot-rte-cmd="bold" title="Bold" aria-label="Bold"><strong>B</strong></button>
                    <button type="button" class="ot-rte__btn" data-ot-rte-cmd="italic" title="Italic" aria-label="Italic"><em>I</em></button>
                    <button type="button" class="ot-rte__btn" data-ot-rte-cmd="underline" title="Underline" aria-label="Underline"><u>U</u></button>
                    <span class="ot-rte__sep" aria-hidden="true"></span>
                    <button type="button" class="ot-rte__btn" data-ot-rte-cmd="insertUnorderedList" title="Bulleted list" aria-label="Bulleted list">&bull; List</button>
                    <button type="button" class="ot-rte__btn" data-ot-rte-cmd="insertOrderedList" title="Numbered list" aria-label="Numbered list">1. List</button>
                    <span class="ot-rte__sep" aria-hidden="true"></span>
                    <button type="button" class="ot-rte__btn" data-ot-rte-cmd="removeFormat" title="Clear formatting" aria-label="Clear formatting">Clear</button>
                  </div>
                  <div class="ot-rte__area"
                       contenteditable="true"
                       data-ot-input
                       data-ot-rich
                       role="textbox"
                       aria-multiline="true"
                       aria-label="{{ qv.al_questiontext | escape }}">{{ existing.al_answerrichtext }}</div>
                </div>
                {% else %}
                <div class="ot-rte__read">{{ existing.al_answerrichtext | default: '&mdash;' }}</div>
                {% endif %}

              {% elsif column == 'date' %}
                <input type="date" data-ot-input{% unless editable %} disabled{% endunless %} value="{{ existing.al_answerdate | date: 'yyyy-MM-dd' }}" aria-label="{{ qv.al_questiontext | escape }}" />

              {% elsif column == 'choices' %}
                {% comment %}
                  Tax check reason (Q-TAX-01), the only multi-select in V8. The shape Liquid
                  gives a multi-select choice column is not documented (the Liquid objects
                  page covers single picklists only), and the label match this used to rely
                  on rendered no selection on a submitted review that held two values. So
                  the checked test accepts every shape the runtime could plausibly return:
                  a collection of option set value objects (folded into a |value| list), a
                  string of comma-separated values, or a string of labels. None of the five
                  values or labels is a substring of another.
                {% endcomment %}
                {% assign mvalues = '120910340,120910341,120910342,120910343,120910344' | split: ',' %}
                {% assign mlabels = 'LSA/LSDBA/TTFAC,Trust,IHT,Tax calculation,Other' | split: ',' %}
                {% assign chosen = '' %}
                {% for c in existing.al_answerchoices %}{% assign chosen = chosen | append: '|' | append: c.value | append: '|' %}{% endfor %}
                <div class="opts">
                  {% for opt in mvalues %}
                    {% assign optkey = '|' | append: opt | append: '|' %}
                    <label class="opt"><input type="checkbox" class="cc-box" data-ot-input value="{{ opt }}"{% unless editable %} disabled{% endunless %}{% if chosen contains optkey or existing.al_answerchoices contains opt or existing.al_answerchoices contains mlabels[forloop.index0] %} checked{% endif %} /> {{ mlabels[forloop.index0] }}</label>
                  {% endfor %}
                </div>

              {% else %}
                {% comment %}
                  PASS and PASS WITH ISSUES come off the grade once a Suitability core check
                  reads Insufficient evidence (item 10, 2026-09-19). Decided here as well as in
                  script so the page arrives right, and so a submitted review - which renders no
                  script - shows what was actually available.
                {% endcomment %}
                {% assign locked_values = '' %}
                {% if rt == 120910010 and suitability_insufficient %}
                  {% assign locked_values = '|120910300|120910303|' %}
                {% endif %}
                {% include 'OT Answer Options' response_type: rt selected: existing.al_answerchoice.value question: qv_id editable: editable is_tax: is_tax_review locked: locked_values %}
              {% endif %}
              </td>
            </tr>
          {% endif %}

          {% assign first_row = false %}
          {% endif %}
        {% endfor %}
        {% endfor %}

        {% comment %}
          Close the last block. This used to hang off forloop.last of the single row loop;
          with sections outer there is no one iteration that is reliably last, so it is done
          once both loops have finished. first_row is still true only when the team's form
          had no rows at all, in which case nothing was ever opened.
        {% endcomment %}
        {% unless first_row %}
          {% if blk_subsections and prev_help != blank %}
            <tr class="lens"{% if lens_tick_id != '' %} data-ot-answer data-question-version="{{ lens_tick_id }}" data-response-type="120910007" data-column="choice"{% endif %}><td colspan="{{ ncols | minus: lens_tick_span }}"><em>Outcome lens:</em> {{ prev_help | escape }}</td>{{ lens_tick_cell }}</tr>{% assign lens_tick_id = '' %}{% assign lens_tick_cell = '' %}{% assign lens_tick_span = 0 %}
          {% endif %}
            </tbody>
          </table>
        {% endunless %}
        </div>
        {% if editable %}
        <script>
          /*
           * Answer autosave and fail points (PP-07, PP-08, FR-013, AD-053, AD-096).
           *
           * Path: page -> Portals Web API PATCH al_reviewinstance.al_answerrequest ->
           * AnswerRequestPlugin -> AnswerWriter -> al_response -> ResponseGuardPlugin.
           *
           * This used to PATCH or POST al_response directly - a create binding two
           * @odata.bind lookups, a ticked reason a $ref associate/disassociate. Power
           * Pages refuses both with error 90040106, and no table permission value fixes
           * it; five were tried. So the page now writes one JSON payload (currentRequest())
           * onto the review instance's al_answerrequest column, which is allowlisted for
           * the Web API, and AnswerRequestPlugin parses it and calls AnswerWriter to do the
           * actual al_response create-or-update and reason reconciliation.
           *
           * This still needs no cloud flow. Submitting reaches Dataverse this same way now
           * too: SubmitRequestPlugin fires off one allowlisted boolean
           * (al_reviewinstance.al_submitrequested) rather than a Power Automate flow, the
           * same AD-053 trigger-column pattern used here - a different reason (the Web API
           * cannot invoke the al_SubmitReview action at all) landing on the same shape.
           * There is no flow run left to spare by debouncing; it now simply keeps a fast
           * typist from spending a synchronous plug-in execution on every keystroke.
           *
           * Every rule that matters - the submission lock, the AD-023 column match, the
           * option subset and AD-020 section ownership - is enforced in the plug-in. This
           * script is convenience, never access control (NFR-SEC-01).
           */
          (function () {
            'use strict';

            var DEBOUNCE_MS = 800;

            var shell = document.querySelector('[data-ot-questionnaire]');
            if (!shell) { return; }
            var REVIEW_ID = shell.getAttribute('data-review-id');
            if (!REVIEW_ID) { return; }

            /*
             * The anti-forgery token comes from shell.getTokenDeferred(), which is the
             * only supported way to obtain it and the way the claim and remediation
             * writes on this site already do it.
             *
             * It used to read a hidden [name="__RequestVerificationToken"] input instead,
             * and guard that read with `if (token)`. Power Pages renders that input on a
             * server-rendered form; this page is a hand-written template and carries no
             * form, so the element never existed, the guard silently dropped the header,
             * and every write left the browser unauthenticated. That is why the refusal
             * was 401 rather than the 403 a table permission produces - the request was
             * never attributed to the signed-in contact at all.
             */
            function api(method, path, body, onDone, onFail) {
              if (!window.shell || typeof window.shell.getTokenDeferred !== 'function') {
                onFail('', 0);
                return;
              }

              window.shell.getTokenDeferred().done(function (token) {
                var xhr = new XMLHttpRequest();
                xhr.open(method, '/_api/' + path, true);
                xhr.setRequestHeader('Content-Type', 'application/json');
                xhr.setRequestHeader('Accept', 'application/json');
                xhr.setRequestHeader('OData-MaxVersion', '4.0');
                xhr.setRequestHeader('OData-Version', '4.0');
                xhr.setRequestHeader('__RequestVerificationToken', token);
                // If-Match: * pins this PATCH to a row that already exists. Without it the
                // Web API treats the PATCH as an upsert, and the Review Instance - assigned
                // to me table permission grants write but not create, so the create half of
                // an upsert is refused. Every caller of api() now PATCHes an al_reviewinstance
                // row the page already loaded, so the header is always safe here - see the
                // submit block below (data-ot-submit script, "If-Match: * matters") for the
                // fuller account of why it exists and what broke without it.
                xhr.setRequestHeader('If-Match', '*');

                xhr.onload = function () {
                  if (xhr.status >= 200 && xhr.status < 300) {
                    onDone(xhr);
                  } else {
                    // The status travels with the body. A refusal carrying no plug-in prefix
                    // did not come from the plug-in at all, and only the status says whether
                    // it was the portal turning the write away or something transient.
                    onFail(xhr.responseText || xhr.statusText, xhr.status);
                  }
                };
                xhr.onerror = function () { onFail('', 0); };
                xhr.send(body ? JSON.stringify(body) : null);
              }).fail(function () { onFail('', 0); });
            }

            /*
             * The plug-in prefixes its failures so the client can branch without parsing
             * prose. Messages say what happened, what is still safe and what to do next,
             * and never expose a table name, query, id or stack trace (PP-16).
             *
             * The status is read as well as the body, because the most common failure here
             * never reaches the plug-in and so carries no prefix: the portal refuses the
             * write on the table permission chain and answers 403. "Not saved - retry" was
             * wrong for that case in the only way that matters - it is not going to work on
             * the retry, or the one after, and the person is given nothing to act on.
             *
             * The write path is Contact-scoped through contact_al_reviewinstance and carried
             * by the two checker web roles, so a 403 means one of exactly two things, and
             * both are worth naming rather than summarising as "permission".
             */
            /*
             * The server's own words, out of the response body.
             *
             * The body is an OData error object, so the message has to be read out of it rather than
             * scanned for in the raw text: a prefix found by indexOf and taken to the end of the
             * string carries the JSON tail with it, which is why the branches below used to cut at
             * the next quote and why one of them did not and showed it.
             *
             * A body that will not parse is returned as it stands - it is still more than "something
             * went wrong" - and it is collapsed onto one line and capped, because an error line is
             * read on screen and the whole of a platform fault is not readable there.
             */
            function serverMessage(raw) {
              var text = String(raw || '').trim();
              if (!text) { return ''; }

              var message = text;
              try {
                var body = JSON.parse(text);
                var error = body && body.error ? body.error : body;
                if (error && error.innererror && error.innererror.message) {
                  message = error.innererror.message;
                } else if (error && error.message) {
                  message = error.message;
                }
              } catch (ignored) {
                // Not JSON. Keep the raw text.
              }

              message = String(message || '').replace(/\s+/g, ' ').trim();
              if (message.length > 300) { message = message.substring(0, 300) + '...'; }
              return message;
            }

            function friendlyError(raw, httpStatus) {
              var text = serverMessage(raw);
              if (text.indexOf('CONFLICT:') !== -1) {
                return 'This review has been submitted and can no longer be changed. Reload the page.';
              }
              if (text.indexOf('UNAUTHORIZED:') !== -1) {
                return 'You do not have permission to change this answer.';
              }
              if (text.indexOf('PRECONDITION:') !== -1) {
                // serverMessage has already taken the message out of the JSON, so this is
                // the message and nothing else. It used to be cut at the next quote to keep
                // the trailing JSON off the screen; that is now unnecessary.
                var idx = text.indexOf('PRECONDITION:');
                return text.substring(idx + 'PRECONDITION:'.length).trim();
              }
              if (text.indexOf('UNEXPECTED:') !== -1) {
                var unexpected = text.indexOf('UNEXPECTED:');
                return 'That answer was not saved. ' + text.substring(unexpected + 'UNEXPECTED:'.length).trim();
              }
              /*
               * 401 and 403 are deliberately not the same message. They were, and that
               * cost three rounds of investigation: a 401 was read as a table permission
               * refusal and sent everyone to look at web roles that were correct all
               * along. The portal answers 403 when the permission chain turns a write
               * away, and 401 when the request never authenticated - an expired session,
               * or a missing anti-forgery token.
               */
              if (httpStatus === 403) {
                return 'Your account is not allowed to record answers on this review, so nothing was saved. '
                  + 'Answering needs a Tax or AQS reviewer role on your portal account, and the review has to be '
                  + 'assigned to you. Ask an administrator to check both - retrying will not help.';
              }
              if (httpStatus === 401) {
                return 'Your session was not accepted, so nothing was saved. Reload the page and sign in again, '
                  + 'then check this answer is still on screen before carrying on.';
              }
              if (httpStatus === 0) {
                return 'That answer did not reach the server. Check your connection; it will save when you next change it.';
              }
              // The server's message rather than "retry": a refusal the page cannot
              // classify is exactly the one whose detail the reader needs.
              return 'Not saved. Your other answers are unaffected.'
                + (text ? ' The server said: ' + text : '')
                + (httpStatus ? ' (status ' + httpStatus + ')' : '');
            }

            // idFromHeader() used to read the new row's id back out of OData-EntityId
            // after a direct al_response create, so save() could remember it for the next
            // PATCH. There is no create here any more - AnswerWriter finds or creates the
            // row server-side - so nothing on this page needs the id, and the function is
            // gone with the create it served.

            function two(n) { return (n < 10 ? '0' : '') + n; }

            function bind(root) {
              var questionVersion = root.getAttribute('data-question-version');
              var column = root.getAttribute('data-column');
              var status = root.querySelector('[data-ot-status]');
              // The standalone fail points list (AD-096) belongs to the File quality outcome
              // answer, so only that answer's bind() finds one; every other answer has none.
              var reasons = document.querySelector('[data-ot-failpoints-for="' + questionVersion + '"]');
              var inputs = root.querySelectorAll('[data-ot-input]');
              var timer = null;

              function show(message, kind) {
                if (!status) { return; }
                status.textContent = message;
                status.className = 'ot-answer__status ot-answer__status--' + kind;
              }

              function chosenChoice() {
                for (var i = 0; i < inputs.length; i++) {
                  if (inputs[i].checked) { return parseInt(inputs[i].value, 10); }
                }
                return null;
              }

              function currentPayload() {
                var body = {};
                var i;

                if (column === 'text') {
                  body.al_answertext = inputs[0].value || null;
                } else if (column === 'richtext') {
                  // What the editor holds, as markup. Sent as it stands: ResponseGuardPlugin
                  // reduces it to the allow-list pre-operation on al_response, so the
                  // cleaning that matters happens where no caller can skip it. Markup with
                  // no words is sent as null, so an emptied editor clears the answer rather
                  // than storing a paragraph holding a line break.
                  var markup = inputs[0].innerHTML;
                  var words = markup.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
                  body.al_answerrichtext = words === '' ? null : markup;
                } else if (column === 'date') {
                  body.al_answerdate = inputs[0].value || null;
                } else if (column === 'choice') {
                  body.al_answerchoice = chosenChoice();
                } else {
                  var picked = [];
                  for (i = 0; i < inputs.length; i++) {
                    if (inputs[i].checked) { picked.push(parseInt(inputs[i].value, 10)); }
                  }
                  // AnswerRequestPlugin's answerChoices is an int[] (AnswerRequest.cs,
                  // AnswerChoices), not the comma-separated value list this used to build -
                  // that format was for the OData multiselect column this page no longer
                  // writes directly. currentRequest() below sends this array through as-is.
                  body.al_answerchoices = picked.length ? picked : null;
                }

                return body;
              }

              /*
               * The answer and its reasons in one object. It travels as a JSON string on
               * al_answerrequest rather than as an al_response create, because Power Pages
               * refuses the create's @odata.bind association (90040106) whatever the table
               * permissions say. AnswerRequestPlugin does the write.
               */
              function currentRequest() {
                var answer = currentPayload();
                var request = {
                  questionVersionId: questionVersion,
                  answerText: answer.al_answertext === undefined ? null : answer.al_answertext,
                  answerRichText: answer.al_answerrichtext === undefined ? null : answer.al_answerrichtext,
                  answerChoice: answer.al_answerchoice === undefined ? null : answer.al_answerchoice,
                  answerChoices: answer.al_answerchoices === undefined ? null : answer.al_answerchoices,
                  answerDate: answer.al_answerdate === undefined ? null : answer.al_answerdate,
                  failReasons: selectedReasonIds(),
                  renderedReasons: renderedReasonIds()
                };
                return request;
              }

              function selectedReasonIds() {
                var boxes = reasons ? reasons.querySelectorAll('[data-ot-reason]') : [];
                var ids = [];
                for (var i = 0; i < boxes.length; i++) {
                  if (boxes[i].checked) { ids.push(boxes[i].value); }
                }
                return ids;
              }

              /*
               * Every reason checkbox the fail points block put on screen, ticked or not -
               * the category-filtered failreasons fetch (template ~line 264), not the full
               * catalogue. AnswerWriter.ReconcileFailReasons only ever disassociates an id
               * that is both in this list and missing from selectedReasonIds(); a reason
               * linked to the answer but outside this list (the other team's category) is
               * left alone, because its absent checkbox never gave the reviewer a chance to
               * untick it (finding 2, 2026-09-08 review).
               */
              function renderedReasonIds() {
                var boxes = reasons ? reasons.querySelectorAll('[data-ot-reason]') : [];
                var ids = [];
                for (var i = 0; i < boxes.length; i++) { ids.push(boxes[i].value); }
                return ids;
              }

              // Nothing on an answer is revealed conditionally any more. The evidence note
              // that revealConditional() used to open on a non-pass is not a field on the
              // Checker Checklist and has been removed, and the fail points block is always
              // on screen (AD-096), so every control an answer has is visible from the start.

              /*
               * One PATCH replaces the create/update pair that used to target al_response
               * directly. The create branch used to set two @odata.bind lookups
               * (al_reviewinstance_response, al_questionversion_response) so Power Pages
               * would associate the new row to its review and question version - and that
               * association is exactly what error 90040106 refuses, whatever the table
               * permissions say. This PATCHes the review instance's al_answerrequest column
               * instead; AnswerRequestPlugin parses the JSON and AnswerWriter does the
               * create-or-update against al_response server-side. The responseId branch and
               * the data-response-id bookkeeping that went with it go with it - there is no
               * create left here to remember an id for.
               */
              function save() {
                var body = { al_answerrequest: JSON.stringify(currentRequest()) };
                show('Saving...', 'saving');

                function done() {
                  var now = new Date();
                  // An answer just saved is no longer one the submit refused for.
                  root.classList.remove('ot-answer--missing');
                  show('Saved ' + two(now.getHours()) + ':' + two(now.getMinutes()), 'saved');
                }

                api('PATCH', 'al_reviewinstances(' + REVIEW_ID + ')', body,
                  done,
                  function (raw, httpStatus) { show(friendlyError(raw, httpStatus), 'error'); });
              }

              function queue() {
                if (timer) { window.clearTimeout(timer); }
                timer = window.setTimeout(save, DEBOUNCE_MS);
              }

              /*
               * A reason is now part of the answer payload, so ticking one is just another
               * change to save. The old "choose an answer first" rule went with the
               * association it protected.
               */
              function toggleReason() {
                queue();
              }

              for (var i = 0; i < inputs.length; i++) {
                inputs[i].addEventListener('change', queue);
                if (inputs[i].tagName === 'TEXTAREA' || inputs[i].type === 'text') {
                  inputs[i].addEventListener('input', queue);
                }
                // contenteditable fires no change event at all, so without this a rich-text
                // answer would save only when something else on the row did.
                if (inputs[i].hasAttribute('data-ot-rich')) {
                  inputs[i].addEventListener('input', queue);
                  inputs[i].addEventListener('blur', queue);
                }
              }

              /*
               * execCommand is deprecated and is still the only thing every browser here
               * implements: there is no replacement API for "bold the selection". The
               * commands offered are the ones HtmlSanitiser keeps, so the toolbar cannot
               * produce formatting the save would discard. mousedown rather than click, and
               * prevented, so pressing a button does not take the selection out of the
               * editor before the command runs on it.
               */
              var area = root.querySelector('[data-ot-rich]');
              if (area) {
                var buttons = root.querySelectorAll('[data-ot-rte-cmd]');
                for (var b = 0; b < buttons.length; b++) {
                  buttons[b].addEventListener('mousedown', function (event) {
                    event.preventDefault();
                    area.focus();
                    try {
                      document.execCommand(this.getAttribute('data-ot-rte-cmd'), false, null);
                    } catch (e) {
                      return; // A browser that refuses the command leaves the text as it was.
                    }
                    queue();
                  });
                }

                // A paste arrives as whatever the source page was. Taking the plain text
                // keeps a paste from Word or a web page out of an answer that would only be
                // stripped back to words on the way in anyway.
                area.addEventListener('paste', function (event) {
                  var clip = event.clipboardData || window.clipboardData;
                  if (!clip) { return; }
                  event.preventDefault();
                  document.execCommand('insertText', false, clip.getData('text/plain') || '');
                  queue();
                });
              }

              // No closure over the box is needed any more: toggleReason() no longer takes
              // one, since a tick is just another field feeding queue() -> save().
              var reasonBoxes = reasons ? reasons.querySelectorAll('[data-ot-reason]') : [];
              for (var r = 0; r < reasonBoxes.length; r++) {
                reasonBoxes[r].addEventListener('change', toggleReason);
              }
            }

            var answers = document.querySelectorAll('[data-ot-answer]');
            for (var i = 0; i < answers.length; i++) { bind(answers[i]); }

            /*
             * The primary root cause appears only while the grade says the file did not pass
             * (item 3, 2026-09-19). The server is where this is actually enforced -
             * SubmitReviewPlugin stops demanding Q-GR-02 on a Pass, and ResponseProgressPlugin
             * clears a cause already recorded - so this is the AD-041 half: it saves a checker
             * answering a question that is about to be taken away from them.
             *
             * Both rows are found by their response type, which is already in the DOM on every
             * answer: the grade's scale belongs to Q-GR-01 and the nine-cause single select to
             * Q-GR-02, and to no other question (AD-055). The template has decided the opening
             * state already, so this only has to keep up with changes.
             */
            var gradeRow = document.querySelector('[data-ot-answer][data-response-type="120910010"]');
            var rootCause = document.querySelector('[data-ot-rootcause]');

            /*
             * Guarded on the grade alone. The two rules below both hang off it, and only one
             * of them needs the root cause block to be on the page - a review whose root cause
             * is hidden must still have its grade options restricted.
             */
            if (gradeRow) {
              var gradeInputs = gradeRow.querySelectorAll('[data-ot-input]');

              // Function expressions rather than declarations: this script runs in strict
              // mode, where a function declared inside a block is not something every
              // engine agrees on, and everything else in this file is ES5.
              var gradeChosen = function () {
                for (var g = 0; g < gradeInputs.length; g++) {
                  if (gradeInputs[g].checked) { return gradeInputs[g].value; }
                }
                return '';
              };

              var syncRootCause = function () {
                if (!rootCause) { return; }
                var grade = gradeChosen();
                var owed = grade !== '' && grade !== '120910300';
                rootCause.hidden = !owed;

                /*
                 * Untick on the way out, so the page stops showing a cause the server is
                 * clearing on this very save. Only on a Pass: that is the grade the server
                 * clears for, and unticking when the grade merely went back to unanswered
                 * would throw away an answer nothing else is removing.
                 *
                 * Nothing is sent from here either way. The grade's own save is what clears
                 * the row, and a second request racing it would be the one to decide which
                 * write landed last.
                 */
                if (grade === '120910300') {
                  var causes = rootCause.querySelectorAll('[data-ot-input]');
                  for (var c = 0; c < causes.length; c++) { causes[c].checked = false; }
                }
              };

              for (var h = 0; h < gradeInputs.length; h++) {
                gradeInputs[h].addEventListener('change', syncRootCause);
              }

              /*
               * Insufficient evidence on a Suitability core check takes PASS and PASS WITH
               * ISSUES off the grade (item 10, 2026-09-19), as soon as the condition is met
               * rather than at submit.
               *
               * The server is where this is enforced: ResponseGuardPlugin refuses either value
               * on the way in, ResponseProgressPlugin clears one already saved when a core
               * check turns Insufficient, and the submit command refuses a review still
               * carrying one. This is the AD-041 half - it stops a checker recording a grade
               * that is about to be taken back off them.
               *
               * The template has already locked the two options where the stored answers meet
               * the condition, so this only has to keep up with what changes on the page.
               */
              var GRADE_PASS = '120910300';
              var GRADE_PASS_WITH_ISSUES = '120910303';
              var INSUFFICIENT = '120910302';

              var suitabilityRows = document.querySelectorAll('[data-ot-suitability]');
              var gradeStatus = gradeRow.querySelector('[data-ot-status]');

              var suitabilityInsufficient = function () {
                for (var r = 0; r < suitabilityRows.length; r++) {
                  var ticks = suitabilityRows[r].querySelectorAll('[data-ot-input]');
                  for (var t = 0; t < ticks.length; t++) {
                    if (ticks[t].checked && ticks[t].value === INSUFFICIENT) { return true; }
                  }
                }
                return false;
              };

              var syncGradeOptions = function () {
                var locked = suitabilityInsufficient();
                var cleared = false;

                for (var g = 0; g < gradeInputs.length; g++) {
                  var input = gradeInputs[g];
                  if (input.value !== GRADE_PASS && input.value !== GRADE_PASS_WITH_ISSUES) {
                    continue;
                  }

                  /*
                   * Unticked before it is disabled. A disabled radio keeps its checked state,
                   * so a grade left selected would still read as chosen to anyone looking at
                   * the page - and would still be sent by the next save of this answer.
                   */
                  if (locked && input.checked) {
                    input.checked = false;
                    cleared = true;
                  }

                  input.disabled = locked;
                  var label = input.parentNode;
                  if (label && label.classList) {
                    if (locked) {
                      label.classList.add('opt--locked');
                    } else {
                      label.classList.remove('opt--locked');
                    }
                  }
                }

                /*
                 * Prompted, because a grade disappearing without a word is the kind of thing a
                 * checker reports as data loss. Nothing is sent from here: the suitability
                 * answer's own save is what clears the stored grade server-side, and a second
                 * request racing it would decide which write landed last.
                 */
                if (cleared && gradeStatus) {
                  gradeStatus.textContent =
                    'Grade cleared \u2014 a Suitability core check reads Insufficient evidence, '
                    + 'so the grade can only be Insufficient evidence or Potential harm.';
                  gradeStatus.className = 'ot-answer__status ot-answer__status--error';
                }

                // The root cause follows the grade, and the grade may have just been cleared.
                syncRootCause();
              };

              for (var sr = 0; sr < suitabilityRows.length; sr++) {
                var ticks = suitabilityRows[sr].querySelectorAll('[data-ot-input]');
                for (var st = 0; st < ticks.length; st++) {
                  ticks[st].addEventListener('change', syncGradeOptions);
                }
              }

              syncGradeOptions();
            }
          })();
        </script>
        {% endif %}

      {% endif %}
    {% endif %}

    {% comment %}
      Remediation and escalation is NOT on this form.

      The document carries it as a closing block marked "(PICKED UP ON ANOTHER FORM)", and
      that is how it is built: al_RemediationAction, al_Signoff and al_Outcome, worked on the
      remediation page and the sign-off step, per case rather than per review (AD-095). This
      page used to render a read-only copy of it beneath the checklist; the project owner's
      direction on 2026-09-09 was that the checklist form is the checklist and remediation
      belongs to its own step, so the copy and its three fetches are gone. Nothing about the
      remediation data changed - only where it is read.
    {% endcomment %}

    {% comment %}
      Submit panel (PP-07, PP-11). Deliberately the last thing on the page.

      It used to sit directly under the summary card, above the questionnaire, so on a
      42-question checklist the button was off-screen by the time a reviewer had answered
      anything and submitting meant scrolling back up past every answer. Submitting is the
      end of the task, so it belongs at the end of the page - reached by finishing the
      questionnaire rather than by scrolling away from it.

      The button is only an affordance: the submission re-checks the transition, every
      mandatory question and the Tax-before-AQS rule server-side, so moving, hiding or
      showing it changes nothing about what is permitted (NFR-SEC-01).
    {% endcomment %}
    {% comment %}
      Who carries the fail (project owner, 2026-09-19), at the end of the check and before
      the Submit button, which is where the checker is when they know the answer.

      Only when this check has failed. Accountability describes a fail: on a clean check
      there is nobody to name, and the server refuses one anyway.

      The four flags live on al_outcome, and that row does not exist yet - SubmitReviewPlugin
      creates it when this review is submitted. So the choice is parked on the review and
      applied to the outcome the submit creates, in the same write as the grade.

      The people come from the contact directory, which checkers can now read: a global
      read-only table permission was added for it (Contact - directory read). They can see
      the directory and still write only their own row, which is the row the request below
      is PATCHed onto.
    {% endcomment %}
    {% if editable %}
      {% comment %}
        The opening state only, not the decision.

        This card is rendered on every editable review and hidden until the check records a
        non-pass; the script below shows and hides it as the answers change. It used to be
        wrapped in this condition instead, which meant the server decided at PAGE LOAD
        whether the card existed - so a checker who ticked Fail saw nothing, because ticking
        an answer autosaves and never re-renders the page. It appeared only after a reload.
        Reported on IO-SEED-TAX-01, 2026-09-19.

        The rule here and the rule in the script are the same one: any answer on the
        outcome scale that is not a plain Pass.
      {% endcomment %}
      {% assign ot_fq_failed = false %}
      {% for a in arows %}
        {% assign ot_ans = a.al_answerchoice.value %}
        {% if ot_ans == 120910301 or ot_ans == 120910302 or ot_ans == 120910303 or ot_ans == 120910304 %}
          {% assign ot_fq_failed = true %}
        {% endif %}
      {% endfor %}

      {% fetchxml directory %}
      <fetch>
        <entity name="contact">
          <attribute name="contactid" />
          <attribute name="fullname" />
          <attribute name="emailaddress1" />
          <filter type="and">
            <condition attribute="statecode" operator="eq" value="0" />
          </filter>
          <order attribute="fullname" />
        </entity>
      </fetch>
      {% endfetchxml %}

      <section class="ot-card ot-accountability"
               data-ot-accountability
               data-review-id="{{ rv.al_reviewinstanceid }}"
               {% unless ot_fq_failed %}hidden{% endunless %}
               aria-labelledby="ot-accountability-heading">
        <h2 class="ot-card__title" id="ot-accountability-heading">Who carries this fail</h2>
        <p>
          This check records a fail. Say who carries it before you submit. Left alone, the
          extract names the people the case itself does: the paraplanner for a File Quality
          fail, the adviser for an Advice Quality fail.
        </p>

        <div class="ot-accountability__grid">
          <fieldset class="ot-accountability__set">
            <legend>File Quality</legend>
            <label class="opt"><input type="checkbox" data-ot-acc="fqParaplanner" /> The paraplanner ({{ rv['case.al_paraplanner'] | default: 'not named' | escape }})</label>
            <label class="opt"><input type="checkbox" data-ot-acc="fqAdviser" /> The adviser ({{ rv['case.al_advisername'] | default: 'not named' | escape }})</label>
            <label class="ot-accountability__person">
              <span>Or someone else</span>
              <input type="text" class="ot-hdr-input" list="ot-acc-people"
                     data-ot-acc-person="fq" placeholder="Search for a person"
                     autocomplete="off" role="combobox"
                     aria-label="Person carrying the File Quality fail" />
            </label>
          </fieldset>

          <fieldset class="ot-accountability__set">
            <legend>Advice Quality</legend>
            <label class="opt"><input type="checkbox" data-ot-acc="aqAdviser" /> The adviser ({{ rv['case.al_advisername'] | default: 'not named' | escape }})</label>
            <label class="opt"><input type="checkbox" data-ot-acc="aqParaplanner" /> The paraplanner ({{ rv['case.al_paraplanner'] | default: 'not named' | escape }})</label>
            <label class="ot-accountability__person">
              <span>Or someone else</span>
              <input type="text" class="ot-hdr-input" list="ot-acc-people"
                     data-ot-acc-person="aq" placeholder="Search for a person"
                     autocomplete="off" role="combobox"
                     aria-label="Person carrying the Advice Quality fail" />
            </label>
          </fieldset>
        </div>

        {% comment %}
          One datalist for both boxes: a datalist is a list of suggestions, not a control,
          so two inputs can point at the same one and it is rendered once rather than twice.

          The option's text is what someone types to choose a person, so it has to identify
          them on its own - name and email together, since two people can share a name. The
          contact's id rides on data-id, because a datalist yields TEXT and cannot carry a
          record; the script maps the text back.
        {% endcomment %}
        <datalist id="ot-acc-people">
          {% for c in directory.results.entities %}
          <option value="{{ c.fullname | escape }} - {{ c.emailaddress1 | escape }}" data-id="{{ c.contactid }}"></option>
          {% endfor %}
        </datalist>

        <p class="ot-accountability__status" data-ot-acc-status role="status" aria-live="polite"></p>
      </section>

      <script>
        (function () {
          'use strict';
          var root = document.querySelector('[data-ot-accountability]');
          if (!root) { return; }

          var status = root.querySelector('[data-ot-acc-status]');
          var reviewId = root.getAttribute('data-review-id');
          var boxes = root.querySelectorAll('[data-ot-acc]');
          var timer = null;
          var saving = false;

          function show(message, kind) {
            status.textContent = message;
            status.className = 'ot-accountability__status' + (kind ? ' ot-inline-status--' + kind : '');
          }

          /*
           * The box IS the search (project owner, 2026-09-19). A native datalist: the
           * browser filters as you type and owns the keyboard, the scrolling and the
           * screen-reader semantics, none of which a hand-rolled list gets right for free.
           *
           * What it costs is that it yields TEXT, not a record, so the text has to identify
           * one person on its own and be mapped back to an id. Anything that matches nobody
           * records nobody, and says so rather than failing at the server.
           */
          var byText = {};
          var options = document.querySelectorAll('#ot-acc-people option');
          for (var o = 0; o < options.length; o++) {
            byText[options[o].value.trim().toLowerCase()] = options[o].getAttribute('data-id');
          }

          function value(name) {
            var box = root.querySelector('[data-ot-acc="' + name + '"]');
            return box ? box.checked : false;
          }

          function person(which) {
            var box = root.querySelector('[data-ot-acc-person="' + which + '"]');
            if (!box) { return ''; }
            var typed = box.value.trim().toLowerCase();
            if (typed === '') { return ''; }
            return byText[typed] || '';
          }

          /** Names anyone the boxes hold text for but could not match. */
          function unmatched() {
            var stray = [];
            var which = ['fq', 'aq'];
            for (var i = 0; i < which.length; i++) {
              var box = root.querySelector('[data-ot-acc-person="' + which[i] + '"]');
              if (box && box.value.trim() !== '' && person(which[i]) === '') {
                stray.push(box.value.trim());
              }
            }
            return stray;
          }

          function save() {
            if (timer) { window.clearTimeout(timer); timer = null; }
            if (saving) { return; }
            if (!window.shell || typeof window.shell.getTokenDeferred !== 'function') {
              show('This page did not load completely. Refresh and try again.', 'error');
              return;
            }

            var stray = unmatched();
            if (stray.length > 0) {
              show('Nobody in the directory matches "' + stray[0] + '", so nobody was'
                + ' recorded for it. Pick a name from the list.', 'error');
              return;
            }

            saving = true;
            show('Saving...', null);

            var body = {
              al_accountabilityrequest: JSON.stringify({
                reviewId: reviewId,
                fqAdviser: value('fqAdviser'),
                fqParaplanner: value('fqParaplanner'),
                aqAdviser: value('aqAdviser'),
                aqParaplanner: value('aqParaplanner'),
                fqContactId: person('fq'),
                aqContactId: person('aq')
              })
            };

            window.shell.getTokenDeferred().done(function (token) {
              var request = new XMLHttpRequest();
              request.open('PATCH', '/_api/contacts({{ user.id }})', true);
              request.setRequestHeader('Content-Type', 'application/json');
              request.setRequestHeader('__RequestVerificationToken', token);

              request.onreadystatechange = function () {
                if (request.readyState !== 4) { return; }
                saving = false;

                if (request.status >= 200 && request.status < 300) {
                  var now = new Date();
                  show('Saved ' + ('0' + now.getHours()).slice(-2) + ':'
                    + ('0' + now.getMinutes()).slice(-2), 'success');
                  return;
                }

                var message = 'That could not be saved (' + request.status + ').';
                try {
                  var parsed = JSON.parse(request.responseText);
                  if (parsed && parsed.error && parsed.error.message) {
                    message = parsed.error.message
                      .replace('PRECONDITION: ', '').replace('VALIDATION: ', '').replace('UNAUTHORIZED: ', '');
                  }
                } catch (e) { /* the status code is all there is */ }
                show(message, 'error');
              };

              request.send(JSON.stringify(body));
            }).fail(function () {
              saving = false;
              show('This page did not load completely. Refresh and try again.', 'error');
            });
          }

          function queue() {
            if (timer) { window.clearTimeout(timer); }
            timer = window.setTimeout(save, 700);
          }

          for (var i = 0; i < boxes.length; i++) { boxes[i].addEventListener('change', queue); }

          // change fires when a suggestion is picked; input covers typing the whole thing
          // out, which a datalist also allows.
          var people = root.querySelectorAll('[data-ot-acc-person]');
          for (var q = 0; q < people.length; q++) {
            people[q].addEventListener('change', queue);
            people[q].addEventListener('input', queue);
          }

          // The submit waits on this the way it waits on the header: a choice made a moment
          // before pressing Submit must reach the review before the outcome is created from it.
          /*
           * Shown and hidden as the answers change (2026-09-19). A non-pass anywhere on the
           * outcome scale means this check recorded a fail and somebody carries it.
           *
           * Bound to the questionnaire rather than to each answer's own save, because an
           * answer is saved on a debounce and the card should appear the moment the option
           * is ticked, not a second later.
           */
          var NON_PASS = ['120910301', '120910302', '120910303', '120910304'];

          function failed() {
            var ticked = document.querySelectorAll('[data-ot-questionnaire] input:checked');
            for (var i = 0; i < ticked.length; i++) {
              for (var n = 0; n < NON_PASS.length; n++) {
                if (ticked[i].value === NON_PASS[n]) { return true; }
              }
            }
            return false;
          }

          function refresh() {
            root.hidden = !failed();
          }

          var questionnaire = document.querySelector('[data-ot-questionnaire]');
          if (questionnaire) {
            questionnaire.addEventListener('change', refresh);
          }

          refresh();

          window.otAccountability = { flush: function (done) { save(); if (done) { done(true); } } };
        })();
      </script>
    {% endif %}

    {% if editable %}
      <section class="ot-card ot-submit"
               data-ot-submit
               data-review-id="{{ rv.al_reviewinstanceid }}"
               aria-labelledby="ot-submit-heading">
        <h2 class="ot-card__title" id="ot-submit-heading">Submit this review</h2>
        <p>
          Submitting locks the review. Every question marked Required must be answered
          first; the check runs server-side, so a missing answer is refused rather than
          silently accepted.
        </p>
        <p>
          <button type="button" class="ot-btn ot-btn--primary" data-ot-submit-button>
            Submit review
          </button>
        </p>
        <p class="ot-submit__status" data-ot-submit-status aria-live="polite"></p>
      </section>
      <script>
        /*
         * Submit Review (PP-07, PP-08, PP-11).
         *
         * Path: review page -> PATCH al_reviewinstance -> SubmitRequestPlugin -> Dataverse.
         *
         * The portals Web API does not support calling actions, so the al_SubmitReview
         * Custom API cannot be invoked from a page. Rather than bridge that with a Power
         * Automate flow, the page sets one allowlisted boolean and a synchronous plug-in
         * does the work - the same mechanic the autosave above already uses for answers
         * (AD-053). Because the step is synchronous, a refusal comes back on this request
         * with its message intact.
         *
         * The request is built exactly like the autosave's api() helper, and that is the
         * point rather than a coincidence. Two writes to the same site over the same API
         * should not be assembled two different ways.
         *
         * They were once reconciled the other way round: this block took its token from
         * shell.getTokenDeferred() and was changed to read the autosave's hidden field
         * because the autosave was "known to work". It was not - no portal write path on
         * this site had ever been exercised by a signed-in user, and the hidden field the
         * autosave read has never existed on this page. Reconciling on an unproven
         * reference moved the working half onto the broken one. Both now use
         * getTokenDeferred(), which is the documented mechanism.
         *
         * If-Match: * matters. Without it a PATCH to the Dataverse Web API is an upsert,
         * and the table permission grants write but not create (see the Review Instance -
         * assigned to me row), so the create half of an upsert is refused. It pins this to
         * an update of a row that already exists.
         *
         * This script is progressive enhancement only. Every rule that matters - the
         * transition, mandatory questions, Tax before AQS, idempotency and the submission
         * lock - is enforced in the plug-in. Disabling the button here is a courtesy to the
         * user, never an access control (NFR-SEC-01).
         */
        (function () {
          'use strict';

          var root = document.querySelector('[data-ot-submit]');
          if (!root) { return; }

          var button = root.querySelector('[data-ot-submit-button]');
          var status = root.querySelector('[data-ot-submit-status]');
          var reviewId = root.getAttribute('data-review-id');

          if (!button || !reviewId) { return; }

          function show(message, kind) {
            if (!status) { return; }
            status.textContent = message;
            status.className = 'ot-submit__status ot-submit__status--' + (kind || 'info');
            status.setAttribute('role', kind === 'error' ? 'alert' : 'status');
          }

          /*
           * The rows the plug-in refused for, marked where they are. Until 2026-09-13 the
           * refusal said "3 of 42 required questions are unanswered" and the page showed
           * that sentence under the button, leaving the checker to scan forty-two rows for
           * three empty ones. The plug-in now names the question version ids; each row
           * carries its own in data-question-version, so the mark lands on the row itself
           * and its status line says why. The first is scrolled into view. A row clears its
           * own mark when its answer next saves. Presentation only - the plug-in still
           * decides (NFR-SEC-01).
           */
          function markUnanswered(ids) {
            var previous = document.querySelectorAll('.ot-answer--missing');
            for (var p = 0; p < previous.length; p += 1) { previous[p].classList.remove('ot-answer--missing'); }

            var first = null;
            for (var i = 0; i < ids.length; i += 1) {
              var id = String(ids[i] || '').trim();
              if (!id) { continue; }
              var rows = document.querySelectorAll('[data-ot-answer][data-question-version="' + id + '"]');
              for (var r = 0; r < rows.length; r += 1) {
                rows[r].classList.add('ot-answer--missing');
                var line = rows[r].querySelector('[data-ot-status]');
                if (line) {
                  line.textContent = 'Required - not answered';
                  line.className = 'ot-answer__status ot-answer__status--error';
                }
                if (!first) { first = rows[r]; }
              }
            }

            if (first && first.scrollIntoView) {
              first.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
          }

          /*
           * The plug-in prefixes its failures so the client can branch without parsing
           * prose. Messages here say what happened, what is still safe, and what to do
           * next, and never expose a table name, query, id or stack trace (PP-16).
           *
           * httpStatus is read as well as the body. A refusal that carries no prefix did
           * not come from the plug-in at all - it came from the portal, before Dataverse
           * was reached - and 401/403 there means the site would not accept the write
           * rather than that anything went wrong transiently. Telling that user to "try
           * again" sends them round a loop that cannot terminate, which is what the single
           * generic message used to do for every non-2xx alike.
           */
          /*
           * The server's own words, out of the response body.
           *
           * The body is an OData error object, so the message has to be read out of it rather than
           * scanned for in the raw text: a prefix found by indexOf and taken to the end of the
           * string carries the JSON tail with it, which is how a PRECONDITION message came to be
           * shown with '","innererror":{...}}' on the end of it.
           *
           * A body that will not parse is returned as it stands - it is still more than "something
           * went wrong" - and it is collapsed onto one line and capped, because an error line is
           * read on screen and the whole of a platform fault is not readable there.
           */
          function serverMessage(raw) {
            var text = String(raw || '').trim();
            if (!text) { return ''; }

            var message = text;
            try {
              var body = JSON.parse(text);
              var error = body && body.error ? body.error : body;
              if (error && error.innererror && error.innererror.message) {
                message = error.innererror.message;
              } else if (error && error.message) {
                message = error.message;
              }
            } catch (ignored) {
              // Not JSON. Keep the raw text.
            }

            return String(message || '').replace(/\s+/g, ' ').trim();
          }

          /*
           * The cap belongs here, not in serverMessage, and that is the whole of a defect
           * found on 2026-09-13.
           *
           * The unanswered-questions refusal carries its question version ids in a bracketed
           * tail at the END of the message, and friendlyError reads that tail to mark the
           * rows. Capping the message before the tail was read cut it off from FOUR
           * unanswered questions upward - 311 characters at four, against a 300 cap - so the
           * rows went unmarked and the text on screen ended mid-identifier. One or three
           * unanswered fitted, which is why it looked like it worked.
           *
           * Each branch below now caps what it actually puts on screen, after the tail has
           * been taken off. An error line is still read on screen, and the whole of a
           * platform fault is still not readable there.
           */
          function cap(text) {
            return text.length > 300 ? text.substring(0, 300) + '...' : text;
          }

          function friendlyError(raw, httpStatus) {
            var text = serverMessage(raw);
            if (text.indexOf('CONFLICT:') !== -1) {
              return 'This review changed since you opened it. Reload the page and try again - your answers are still saved.';
            }
            if (text.indexOf('UNAUTHORIZED:') !== -1) {
              return 'You do not have permission to submit this review.';
            }
            if (text.indexOf('PRECONDITION:') !== -1) {
              // Carries the actionable detail: which required questions remain, by code, and
              // in a bracketed tail their question version ids, which mark the rows below and
              // are never shown.
              var idx = text.indexOf('PRECONDITION:');
              var detail = text.substring(idx + 'PRECONDITION:'.length).trim();
              var tail = /\s*\[unanswered:([^\]]*)\]\s*$/.exec(detail);
              if (tail) {
                markUnanswered(tail[1].split(','));
                detail = detail.substring(0, tail.index).trim();
              }
              return cap(detail);
            }
            if (text.indexOf('UNEXPECTED:') !== -1) {
              var unexpected = text.indexOf('UNEXPECTED:');
              return 'This review was not submitted. ' + cap(text.substring(unexpected + 'UNEXPECTED:'.length).trim());
            }
            if (httpStatus === 403) {
              /*
               * Reloading and trying once more was the wrong advice: this refusal is the
               * permission chain, and it will refuse again.
               *
               * It also used to promise "your answers are still saved", and that promise was
               * false in the case that produces it. Answering and submitting travel the same
               * Contact-scoped permission chain, so an account refused here was refused on
               * every autosave too - the answers were never written, and a reader who trusts
               * the message loses the lot on reload. Reported exactly that way. It now says
               * what is true, which is that it does not know.
               */
              return 'Your account is not allowed to submit this review, so nothing was submitted. Check your answers '
                + 'are still on screen before leaving the page - the same permission stops them being saved, so they '
                + 'may not have been. Submitting needs a Tax or AQS reviewer role on your portal account, and the '
                + 'review has to be assigned to you. Ask an administrator to check both rather than retrying.';
            }
            /*
             * Split from 403 for the reason given on the autosave's friendlyError: a 401
             * is the session, not the permission chain, and conflating them sent three
             * rounds of investigation at web roles that were correct.
             */
            if (httpStatus === 401) {
              return 'Your session was not accepted, so nothing was submitted. Reload the page and sign in again, '
                + 'then check your answers are still on screen before submitting.';
            }
            /*
             * The server's message rather than an invented sentence. "We could not submit
             * this review, please try again" was true of every refusal alike and told the
             * reader nothing they could act on or quote - which is what was reported on
             * 2026-09-10, against a refusal whose real cause the page had been handed and
             * discarded.
             */
            return 'This review was not submitted, and nothing has been changed. '
              + (text ? 'The server said: ' + cap(text) : 'The server gave no detail.')
              + (httpStatus ? ' (status ' + httpStatus + ')' : '');
          }

          function setBusy(busy) {
            button.disabled = busy;
            button.setAttribute('aria-busy', busy ? 'true' : 'false');
            button.textContent = busy ? 'Submitting...' : 'Submit review';
          }

          /*
           * What the server render does for a submitted review, done to the page in hand:
           * every control the questionnaire owns is disabled and the submit button stays
           * disabled, leaving the status line so the confirmation stays readable. The
           * autosave script sees disabled controls as nothing to save.
           */
          /*
           * 'dd MMM yyyy', the format the Liquid date filter renders into the cell below, so
           * the date this writes cannot be told from the date the server drew.
           */
          function today() {
            var now = new Date();
            var day = now.getDate();
            var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                          'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            return (day < 10 ? '0' + day : String(day)) + ' ' + months[now.getMonth()] + ' ' + now.getFullYear();
          }

          /*
           * Locking the controls is not the whole of what a submit changes on this page.
           *
           * The summary above carries the review's status and its Submitted date, both
           * server-rendered, and neither moved when the page stopped reloading after a
           * submit (AD-094). So a submitted review sat there reading "In progress" and "—"
           * under a message saying it was submitted and locked - the same contradiction
           * reported on IO-300001's regrade, which is AD-130.
           *
           * Both are certain here: the PATCH returned 2xx, so the review IS submitted, by
           * this person, today. The badge class mirrors OT Status Badge, where 'Submitted'
           * matches its 'submitted' branch and is ot-badge--active.
           */
          function markSubmitted() {
            var status = document.querySelector('[data-ot-review-status]');
            if (status) {
              status.textContent = '';
              var badge = document.createElement('span');
              badge.className = 'ot-badge ot-badge--active';
              badge.textContent = 'Submitted';
              status.appendChild(badge);
            }

            var when = document.querySelector('[data-ot-submitted-on]');
            if (when) { when.textContent = today(); }
          }

          function lockPage() {
            var controls = document.querySelectorAll(
              '[data-ot-questionnaire] input, [data-ot-questionnaire] textarea, [data-ot-questionnaire] select, [data-ot-questionnaire] button');
            for (var i = 0; i < controls.length; i++) { controls[i].disabled = true; }
            button.disabled = true;
            button.textContent = 'Submitted';
            button.setAttribute('aria-busy', 'false');
            markSubmitted();
          }

          button.addEventListener('click', function () {
            if (button.disabled) { return; }

            if (!window.shell || typeof window.shell.getTokenDeferred !== 'function') {
              show('This page did not load completely. Refresh and try again.', 'error');
              return;
            }

            /*
             * Any outstanding header edit first (project owner, 2026-09-19).
             *
             * The header saves itself as it is edited, so there is usually nothing waiting -
             * but a field changed a moment before the click can still be inside its
             * debounce, and submitting on top of it would store the review against a header
             * the checker had already corrected. A header edit that will not save stops the
             * submit rather than being lost under it: the review is the thing that cannot be
             * taken back (BR-012).
             */
            // The accountability choice, if the checker made one a moment ago: it is parked
            // on the review and the submit is what turns it into part of the outcome, so it
            // has to land first.
            if (window.otAccountability && typeof window.otAccountability.flush === 'function') {
              window.otAccountability.flush(null);
            }

            if (window.otHeader && typeof window.otHeader.flush === 'function') {
              setBusy(true);
              show('Saving your header changes...', 'info');
              window.otHeader.flush(function (ok) {
                if (!ok) {
                  show('Your header changes could not be saved, so the review was not'
                    + ' submitted. Fix that first - the message beside the header says why.',
                    'error');
                  setBusy(false);
                  return;
                }
                submit();
              });
              return;
            }

            submit();
          });

          function submit() {
            setBusy(true);
            show('Submitting your review...', 'info');

            function unreachable() {
              show('The submission did not reach the server. Check your connection and try again - your answers are still saved.', 'error');
              setBusy(false);
            }

            // Power Pages requires the request verification token on every write, and
            // shell.getTokenDeferred() is the only supported way to obtain it. Same
            // mechanism the autosave above uses, so both writes present the same
            // credential - which is what the hidden-field read was meant to achieve and
            // did not, because this page renders no form to carry that field.
            window.shell.getTokenDeferred().done(function (token) {
              var request = new XMLHttpRequest();
              request.open('PATCH', '/_api/al_reviewinstances(' + reviewId + ')', true);
              request.setRequestHeader('Content-Type', 'application/json');
              request.setRequestHeader('Accept', 'application/json');
              request.setRequestHeader('OData-MaxVersion', '4.0');
              request.setRequestHeader('OData-Version', '4.0');
              request.setRequestHeader('If-Match', '*');
              request.setRequestHeader('__RequestVerificationToken', token);

              request.onload = function () {
                if (request.status >= 200 && request.status < 300) {
                  /*
                   * Locked here, in the page already on screen, rather than by reloading.
                   * Power Pages renders from a server-side cache that a website write clears
                   * only for the record it wrote; al_submittedon is stamped by
                   * SubmitRequestPlugin and every answer row was created by AnswerWriter, so
                   * a reload straight after the PATCH could render the pre-submit review as
                   * still editable with no answers on it (AD-094). Change tracking on the
                   * portal tables is what makes the next visit right; not reloading is what
                   * makes this one right.
                   */
                  lockPage();
                  show('Review submitted. This review is now locked; reopening or regrading is a T&C Manager action.', 'success');
                  return;
                }

                show(friendlyError(request.responseText, request.status), 'error');
                setBusy(false);
              };

              request.onerror = unreachable;

              request.send(JSON.stringify({ al_submitrequested: true }));
            }).fail(unreachable);
          }
        })();
      </script>
    {% endif %}

    {% comment %}
      Saving the Tax team's two header fields. Rendered only where the controls are: a Tax
      review that has not been submitted.

      The write is a PATCH of one JSON column on the signed-in user's OWN contact row, which
      is the only shape this site accepts - a browser write on al_outcomecase is refused with
      90040106 whatever the table permissions say, the same refusal and the same resolution
      as the answer (AD-053), the claim (AD-076) and the sign-off (AD-099). The site's
      contact permission is Self-scoped, so the request can only ever reach the signed-in
      user's row, and CaseHeaderRequestPlugin takes the editor from the row it was given
      rather than from anything sent here.

      The token comes from shell.getTokenDeferred(), the only supported way to obtain it and
      the way every other write on this site does it. Reading a hidden input instead is what
      once left every write unauthenticated, because this page carries no server-rendered
      form for Power Pages to put that input on.

      An unchanged field is sent as 0, which the plug-in reads as "not sent" and leaves
      alone. Sending the current value instead would be harmless but would put a field in the
      audit line that nobody moved.
    {% endcomment %}
    {% if locked == false %}
      <script>
        (function () {
          var status = document.getElementById('ot-header-status');
          if (!status) { return; }

          var DEBOUNCE_MS = 900;
          var timer = null;
          var saving = false;

          /*
           * The Tax team's two selects exist only on an unsubmitted Tax review. Everything
           * else on the header is editable on any open review, so both are optional here
           * and the payload names only what is present and changed.
           */
          var required = document.getElementById('ot-taxrequired');
          var disposition = document.getElementById('ot-taxdisposition');

          var initialRequired = required ? required.value : '';
          var initialDisposition = disposition ? disposition.value : '';

          // The rest of the header, remembered as rendered so an untouched field is never
          // sent. Sending the current value would be harmless but would put a field in the
          // audit line that nobody moved.
          var headerInputs = [];
          var rendered = document.querySelectorAll('[data-ot-hdr]');
          for (var h = 0; h < rendered.length; h++) {
            headerInputs.push({ el: rendered[h], initial: rendered[h].value });
          }

          /*
           * Today in the UK, as yyyy-MM-dd (item 9, 2026-09-19).
           *
           * Users are in the UK and the browser may not be, and on a British Summer Time
           * evening even a UK machine reading UTC is a day behind - a checker entering
           * their own today would be refused. en-CA is used because it formats as
           * YYYY-MM-DD, which is what a date input takes. The app reads the day the same
           * way in caseHeaderDates.ts, and CaseHeaderRules is the authority server-side.
           */
          function ukToday() {
            try {
              return new Intl.DateTimeFormat('en-CA', {
                timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit'
              }).format(new Date());
            } catch (e) {
              // A runtime without the zone data still gets a cap, just the browser's own
              // day. The command refuses a future date whatever the page allowed.
              return new Date().toISOString().slice(0, 10);
            }
          }

          /*
           * A meeting that has not happened yet cannot have been checked, so the picker
           * will not offer a future day. An affordance only: al_CaseHeaderRequest reaches
           * the same rule through ApplyFields, because a typed date gets past a max on
           * some browsers and the request can be made by hand in any case.
           */
          var noFuture = document.querySelectorAll('[data-ot-no-future]');
          for (var n = 0; n < noFuture.length; n++) {
            noFuture[n].setAttribute('max', ukToday());
          }

          /** The changed header fields, as the flat object the plug-in parses. */
          function changedFields() {
            var fields = {};
            var any = false;
            for (var i = 0; i < headerInputs.length; i++) {
              var entry = headerInputs[i];
              if (entry.el.value === entry.initial) { continue; }
              fields[entry.el.getAttribute('data-ot-hdr')] = entry.el.value;
              any = true;
            }
            return any ? fields : null;
          }

          function show(message, kind) {
            status.textContent = message;
            status.className = kind ? 'ot-inline-status ot-inline-status--' + kind : 'ot-inline-status';
          }

          /*
           * The reload the reader asks for, added once beside the status line. A button
           * rather than a timer, for the reason the success branch below gives: the page
           * cannot promise that a reload shows the new state, so it must not spring one.
           */
          function offerReload() {
            if (status.parentNode.querySelector('[data-ot-reload]')) { return; }
            var button = document.createElement('button');
            button.type = 'button';
            button.className = 'ot-btn';
            button.setAttribute('data-ot-reload', '');
            button.textContent = 'Reload the page';
            button.addEventListener('click', function () { window.location.reload(); });
            status.parentNode.insertBefore(button, status.nextSibling);
          }

          function friendly(body, code) {
            // The server's own words where it gave any: the refusals here are business
            // rules - the role, and the review already being submitted - and a checker can
            // act on both. A bare status code cannot be acted on by anyone.
            try {
              var parsed = JSON.parse(body);
              var text = parsed && parsed.error && parsed.error.message;
              if (text) {
                return text
                  .replace('PRECONDITION: ', '')
                  .replace('VALIDATION: ', '')
                  .replace('UNAUTHORIZED: ', '');
              }
            } catch (e) { /* fall through to the code */ }
            if (code === 403) { return 'Your portal account is not permitted to change these fields.'; }
            return 'The change could not be saved (' + code + ').';
          }

          /*
           * Saves whatever has moved, or reports that nothing has.
           *
           * `done` is called with true when there was nothing to save or the save
           * succeeded, and false when it failed. The submit waits on it, so a header edit
           * that could not be stored stops the review being submitted on top of it rather
           * than being lost quietly.
           */
          function saveNow(done) {
            done = done || function () {};

            if (timer) { window.clearTimeout(timer); timer = null; }
            if (saving) { done(true); return; }

            var fields = changedFields();
            var taxMoved = (required && required.value !== initialRequired)
              || (disposition && disposition.value !== initialDisposition);

            if (!fields && !taxMoved) { done(true); return; }

            saving = true;
            show('Saving...', null);

            if (!window.shell || typeof window.shell.getTokenDeferred !== 'function') {
              show('This page did not load completely. Refresh and try again.', 'error');
              saving = false;
              done(false);
              return;
            }

            var request_body = {
              caseId: status.getAttribute('data-case-id'),
              taxCheckRequired: (required && required.value !== initialRequired)
                ? parseInt(required.value || '0', 10) : 0,
              taxTeamDisposition: (disposition && disposition.value !== initialDisposition)
                ? parseInt(disposition.value || '0', 10) : 0
            };

            // Only when something moved: an empty object would make the plug-in read this
            // as a header edit and run the assignment guard for no reason.
            if (fields) { request_body.fields = JSON.stringify(fields); }

            var payload = { al_caseheaderrequest: JSON.stringify(request_body) };

            window.shell.getTokenDeferred().done(function (token) {
              var request = new XMLHttpRequest();
              request.open('PATCH', '/_api/contacts({{ user.id }})', true);
              request.setRequestHeader('Content-Type', 'application/json');
              request.setRequestHeader('__RequestVerificationToken', token);

              request.onreadystatechange = function () {
                if (request.readyState !== 4) { return; }
                saving = false;

                if (request.status >= 200 && request.status < 300) {
                  var routeMayHaveMoved = (required && required.value !== initialRequired)
                    || (disposition && disposition.value !== initialDisposition);

                  if (required) { initialRequired = required.value; }
                  if (disposition) { initialDisposition = disposition.value; }
                  for (var k = 0; k < headerInputs.length; k++) {
                    headerInputs[k].initial = headerInputs[k].el.value;
                  }

                  if (!routeMayHaveMoved) {
                    // An ordinary header field. Nothing else on the page depends on it, so
                    // it is confirmed the way a saved answer is and nothing is offered.
                    var now = new Date();
                    show('Saved ' + ('0' + now.getHours()).slice(-2) + ':'
                      + ('0' + now.getMinutes()).slice(-2), 'success');
                    done(true);
                    return;
                  }
                  /*
                   * Confirmed in place, and the reload offered rather than taken.
                   *
                   * The rows this write changes are al_outcomecase and, where the route
                   * re-derives (BR-004), the review instances - and the page wrote none of
                   * them. It PATCHed contact.al_caseheaderrequest and CaseHeaderRequestPlugin
                   * did the rest, so the portal's render cache is not invalidated by this
                   * write path and learns through change tracking (AD-094), which is polled.
                   * An immediate reload therefore re-draws the Review progress table exactly
                   * as it was, under a success message - which is what three reports on
                   * OT Remediation turned out to be on 2026-09-13 (AD-126, AD-127, AD-128).
                   *
                   * The two selects already show what was saved, because the reader chose
                   * them. What the page cannot know is whether the route moved, so it says
                   * that plainly instead of showing a stale answer to it.
                   */
                  show('Saved. The route can change with these fields, and Review progress'
                    + ' above still shows what the page read before you saved. Reload it when'
                    + ' you want that re-read, and if it still looks unchanged the site cache'
                    + ' has not caught up - try again in a moment.', 'success');
                  offerReload();
                  done(true);
                  return;
                }

                show(friendly(request.responseText, request.status), 'error');
                done(false);
              };

              request.onerror = function () {
                saving = false;
                show('The change could not be saved. Check your connection and try again.', 'error');
                done(false);
              };

              request.send(JSON.stringify(payload));
            }).fail(function () {
              saving = false;
              show('This page did not load completely. Refresh and try again.', 'error');
              done(false);
            });
          }

          /** Saves shortly after typing stops, so a half-typed name is not sent per keystroke. */
          function queue() {
            if (timer) { window.clearTimeout(timer); }
            timer = window.setTimeout(function () { saveNow(); }, DEBOUNCE_MS);
          }

          for (var b = 0; b < headerInputs.length; b++) {
            var control = headerInputs[b].el;
            control.addEventListener('change', queue);
            if (control.tagName === 'INPUT' && control.type === 'text') {
              control.addEventListener('input', queue);
            }
            // Leaving a field is a decision. Saving on blur as well as on the timer means a
            // checker who edits and immediately submits does not race the debounce.
            control.addEventListener('blur', function () { saveNow(); });
          }

          if (required) { required.addEventListener('change', function () { saveNow(); }); }
          if (disposition) { disposition.addEventListener('change', function () { saveNow(); }); }

          /*
           * What the submit waits on. The header saves itself as it is edited, so by the
           * time anyone submits there is usually nothing outstanding - but a field changed a
           * moment earlier can still be inside the debounce, and submitting on top of it
           * would store the review against a header the checker had already corrected.
           */
          window.otHeader = {
            flush: function (done) { saveNow(done); }
          };
        })();
      </script>
    {% endif %}
  {% endif %}
{% endif %}
{% endblock %}
"
}
